INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-001', 'HDSAT-M-ADV-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Equivalent expressions', 'Easy', 'multiple_choice', '$$(2x^2 - 5x + 3) - (x^2 - 4x - 7)$$', 'Which of the following is equivalent to the given expression?', '[{"id": "A", "text": "$x^2 - 9x - 4$"}, {"id": "B", "text": "$x^2 - x - 4$"}, {"id": "C", "text": "$x^2 - x + 10$"}, {"id": "D", "text": "$3x^2 - 9x + 10$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-002', 'HDSAT-M-ADV-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear functions', 'Medium', 'multiple_choice', 'The height $h(t)$, in meters above the ground, of a weather probe launched vertically from a platform is modeled by the function $h(t) = -5t^2 + 40t + 12$, where $t$ is the time in seconds after launch.', 'What is the maximum height, in meters, reached by the probe?', '[{"id": "A", "text": "$52$"}, {"id": "B", "text": "$92$"}, {"id": "C", "text": "$4$"}, {"id": "D", "text": "$80$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-003', 'HDSAT-M-ADV-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear equations in one variable and systems of equations in two variables', 'Medium', 'spr', '$$x^2 - 11x + 24 = 0$$', 'What is the positive difference between the two solutions to the given quadratic equation?', NULL, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-004', 'HDSAT-M-ADV-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear functions', 'Hard', 'multiple_choice', 'A culture of bioluminescent bacteria initially contains $2{,}500$ cells. Under controlled nutrient conditions, the population doubles every $3$ hours.', 'Which function $P(t)$ best models the number of bacteria in the culture $t$ hours after the start of the observation?', '[{"id": "A", "text": "$P(t) = 2{,}500(3)^{t/2}$"}, {"id": "B", "text": "$P(t) = 2{,}500(2)^{t/3}$"}, {"id": "C", "text": "$P(t) = 2{,}500 + 2^{t/3}$"}, {"id": "D", "text": "$P(t) = 2{,}500(2)^{3t}$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-005', 'HDSAT-M-ADV-005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear equations in one variable and systems of equations in two variables', 'Hard', 'spr', '$$2x^2 - 12x + c = 0$$', 'In the given equation, $c$ is a constant. If the equation has exactly one real solution, what is the value of $c$?', NULL, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-001', 'HDSAT-M-PSD-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Percentages', 'Easy', 'multiple_choice', 'During an annual clearance sale, a scientific instrument supplier reduces the price of a digital oscilloscope by $20\%$. A university laboratory also applies an educational grant discount that takes an additional $10\%$ off the sale price.', 'If the original list price of the oscilloscope was $\$650$, what is the final price paid by the laboratory, before tax?', '[{"id": "A", "text": "$\\$468$"}, {"id": "B", "text": "$\\$520$"}, {"id": "C", "text": "$\\$585$"}, {"id": "D", "text": "$\\$455$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-002', 'HDSAT-M-PSD-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'One-variable data: distributions and measures of center and spread', 'Medium', 'spr', 'The table shows the daily particulate matter readings (in micrograms per cubic meter) recorded at an air-quality station over $6$ days. On Day 7, a reading of $92$ micrograms per cubic meter is recorded due to a regional dust event.', 'By how much does the mean of the $7$-day dataset exceed the median of the $7$-day dataset?', NULL, '{"type": "table", "caption": "Daily Particulate Matter Readings (Days 1–6)", "headers": ["Day", "Reading (µg/m³)"], "rows": [["Day 1", "14"], ["Day 2", "18"], ["Day 3", "21"], ["Day 4", "21"], ["Day 5", "25"], ["Day 6", "33"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-003', 'HDSAT-M-PSD-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Probability and conditional probability', 'Medium', 'multiple_choice', 'A quality-control engineer inspected $240$ solar panels from two production lines and recorded the results in the table.', 'If one of the panels that passed inspection is selected at random, what is the probability that it was manufactured on Line A?', '[{"id": "A", "text": "$\\dfrac{7}{12}$"}, {"id": "B", "text": "$\\dfrac{44}{75}$"}, {"id": "C", "text": "$\\dfrac{11}{20}$"}, {"id": "D", "text": "$\\dfrac{33}{35}$"}]'::jsonb, '{"type": "table", "caption": "Solar Panel Quality Inspection", "headers": ["Production Line", "Passed", "Failed", "Total"], "rows": [["Line A", "132", "8", "140"], ["Line B", "93", "7", "100"], ["Total", "225", "15", "240"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-004', 'HDSAT-M-PSD-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Inference from sample statistics and margin of error', 'Hard', 'multiple_choice', 'A transit authority surveyed a random sample of $400$ weekday commuter-rail riders in a metropolitan region. Based on the sample, the authority estimated that $64\%$ of all weekday commuter-rail riders in the region use mobile ticketing, with an associated margin of error of $4.5\%$ at the $95\%$ confidence level.', 'Which of the following is the most appropriate conclusion from the survey?', '[{"id": "A", "text": "It is plausible that the actual percentage of all weekday commuter-rail riders in the region who use mobile ticketing is between $59.5\\%$ and $68.5\\%$."}, {"id": "B", "text": "If the transit authority surveyed another $400$ riders, the new sample proportion would be guaranteed to equal $64\\%$."}, {"id": "C", "text": "Among the $400$ sampled riders, between $59.5\\%$ and $68.5\\%$ stated that they were $95\\%$ satisfied with mobile ticketing."}, {"id": "D", "text": "Exactly $64\\%$ of all transit riders across every mode of transportation in the region use mobile ticketing."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-001', 'HDSAT-M-GEO-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Area and volume', 'Easy', 'spr', 'A right circular cylinder has a base radius of $4$ centimeters and a height of $9$ centimeters. The volume of the cylinder can be written in the form $k\pi$ cubic centimeters, where $k$ is a constant.', 'What is the value of $k$?', NULL, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-002', 'HDSAT-M-GEO-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Right triangles and trigonometry', 'Medium', 'multiple_choice', 'In right triangle $ABC$, angle $C$ is a right angle, the length of side $AC$ is $12$, and the length of hypotenuse $AB$ is $15$.', 'What is the value of $\sin A$?', '[{"id": "A", "text": "$\\dfrac{4}{5}$"}, {"id": "B", "text": "$\\dfrac{3}{4}$"}, {"id": "C", "text": "$\\dfrac{3}{5}$"}, {"id": "D", "text": "$\\dfrac{4}{3}$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-003', 'HDSAT-M-GEO-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Circles', 'Hard', 'multiple_choice', '$$x^2 + y^2 - 6x + 8y - 11 = 0$$', 'The equation above represents a circle in the $xy$-plane. What is the radius of the circle?', '[{"id": "A", "text": "$\\sqrt{11}$"}, {"id": "B", "text": "$36$"}, {"id": "C", "text": "$6$"}, {"id": "D", "text": "$5$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-004', 'HDSAT-M-GEO-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Circles', 'Hard', 'spr', 'A circle in the $xy$-plane has radius $10$. Sector $AOB$ of the circle has a central angle of $\dfrac{2\pi}{5}$ radians. The area of sector $AOB$ can be written as $m\pi$, where $m$ is a constant.', 'What is the value of $m$?', NULL, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
