INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-200', 'HDSAT-RW-INF-200', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'Researchers compiled data on urban tree canopy vs. summer surface temperature and concluded: Canopy cover rather than latitude best predicts which streets stay cool in heat waves.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "Iron Row recorded the smallest value for every measured outcome."}, {"id": "B", "text": "Maple Heights (38% canopy) peaks at 31.2 C while Iron Row (11%) peaks at 38.7 C and Dock Quarter (5%) at 41.0 C."}, {"id": "C", "text": "The data show no consistent relationship between the measured variables."}, {"id": "D", "text": "Cedar Flats reversed the direction of the effect reported in the conclusion."}]'::jsonb, '{"type": "table", "caption": "Urban tree canopy vs. summer surface temperature", "headers": ["Neighborhood", "Canopy Cover (%)", "Peak Surface Temp (C)"], "rows": [["Maple Heights", "38", "31.2"], ["Iron Row", "11", "38.7"], ["Cedar Flats", "25", "33.9"], ["Dock Quarter", "5", "41.0"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-201', 'HDSAT-RW-INF-201', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'The figure summarizes a regional study on urban tree canopy vs. summer surface temperature.', 'Which statement is best supported by the data in the figure?', '[{"id": "A", "text": "Every category differs from the next by the exact same margin, so no ranking is possible."}, {"id": "B", "text": "Maple Heights is the single most extreme value across all categories, dominating every comparison."}, {"id": "C", "text": "The pattern is monotonic: less canopy, hotter surfaces."}, {"id": "D", "text": "The predictors are causally established by the summary figure alone, not merely correlated."}]'::jsonb, '{"type": "table", "caption": "Urban tree canopy vs. summer surface temperature", "headers": ["Neighborhood", "Canopy Cover (%)", "Peak Surface Temp (C)"], "rows": [["Maple Heights", "38", "31.2"], ["Iron Row", "11", "38.7"], ["Cedar Flats", "25", "33.9"], ["Dock Quarter", "5", "41.0"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, 