INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-202', 'HDSAT-RW-INF-202', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'Researchers compiled data on museum visit recovery after renovation and concluded: Attendance recovered steadily in the year after the gallery wing reopened.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "Visitors rise every quarter: 18.4 -> 22.1 -> 29.6 -> 35.2 thousand."}, {"id": "B", "text": "Q1 (renovated) recorded the smallest value for every measured outcome."}, {"id": "C", "text": "Q2 reversed the direction of the effect reported in the conclusion."}, {"id": "D", "text": "The data show no consistent relationship between the measured variables."}]'::jsonb, '{"type": "table", "caption": "Museum visit recovery after renovation", "headers": ["Quarter", "Visitors (thousands)"], "rows": [["Q1 (renovated)", "18.4"], ["Q2", "22.1"], ["Q3", "29.6"], ["Q4", "35.2"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
