INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-204', 'HDSAT-RW-INF-204', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'Researchers compiled data on seedling survival by watering regime and concluded: Fewer, deeper waterings outperform frequent shallow ones for survival.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "Weekly deep reversed the direction of the effect reported in the conclusion."}, {"id": "B", "text": "Weekly deep watering wins (83%) despite all regimes planting 500 seedlings each."}, {"id": "C", "text": "Twice weekly recorded the smallest value for every measured outcome."}, {"id": "D", "text": "The data show no consistent relationship between the measured variables."}]'::jsonb, '{"type": "table", "caption": "Seedling survival by watering regime", "headers": ["Regime", "Seedlings Planted", "Survived (%)"], "rows": [["Daily light", "500", "62%"], ["Twice weekly", "500", "71%"], ["Weekly deep", "500", "83%"], ["Rain-fed only", "500", "58%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXC