INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-206', 'HDSAT-RW-INF-206', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'Researchers compiled data on library e-book borrows by patron age band and concluded: Working-age adults account for most of the e-book program''s use.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "The data show no consistent relationship between the measured variables."}, {"id": "B", "text": "25-39 reversed the direction of the effect reported in the conclusion."}, {"id": "C", "text": "25-39 plus 40-64 sum to 58.4 thousand of the 80.8 total, well over half."}, {"id": "D", "text": "18-24 recorded the smallest value for every measured outcome."}]'::jsonb, '{"type": "table", "caption": "Library e-book borrows by patron age band", "headers": ["Age Band", "Borrowed (thousands)"], "rows": [["18-24", "12.6"], ["25-39", "31.4"], ["40-64", "27.0"], ["65+", "9.8"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
