INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-208', 'HDSAT-RW-INF-208', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'Researchers compiled data on night-shift alertness by break schedule and concluded: More frequent short breaks reduce lapses more than one long break.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "The data show no consistent relationship between the measured variables."}, {"id": "B", "text": "Micro-breaks hourly reversed the direction of the effect reported in the conclusion."}, {"id": "C", "text": "Hourly micro-breaks produce the fewest lapses (3.4), versus 6.1 for one long break."}, {"id": "D", "text": "Two 15-min breaks recorded the smallest value for every measured outcome."}]'::jsonb, '{"type": "table", "caption": "Night-shift alertness by break schedule", "headers": ["Schedule", "Avg. lapses per shift"], "rows": [["Single 30-min break", "6.1"], ["Two 15-min breaks", "5.2"], ["Micro-breaks hourly", "3.4"], ["No scheduled break", "8.9"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status =