INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-209', 'HDSAT-RW-INF-209', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'The figure summarizes a regional study on night-shift alertness by break schedule.', 'Which statement is best supported by the data in the figure?', '[{"id": "A", "text": "Every category differs from the next by the exact same margin, so no ranking is possible."}, {"id": "B", "text": "Single 30-min break is the single most extreme value across all categories, dominating every comparison."}, {"id": "C", "text": "The predictors are causally established by the summary figure alone, not merely correlated."}, {"id": "D", "text": "Hourly micro-breaks produce the fewest lapses (3.4), versus 6.1 for one long break."}]'::jsonb, '{"type": "bar_chart", "caption": "Night-shift alertness by break schedule", "x_label": "Schedule", "y_label": "Avg. lapses per shift", "series": [{"label": "Single 30-min break", "value": 6.1}, {"label": "Two 15-min breaks", "value": 5.2}, {"label": "Micro-breaks hourly", "value": 3.4}, {"label": "No scheduled break", "value": 8.9}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDE