INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-210', 'HDSAT-RW-INF-210', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'Researchers compiled data on compost feedstock and finished-soil nitrogen and concluded: Protein-rich feedstocks raise soil nitrogen most.', 'Which finding from the data best supports the researchers'' conclusion?', '[{"id": "A", "text": "Fish waste (1,905 mg/kg) exceeds coffee grounds and both plant feedstocks."}, {"id": "B", "text": "Leaf litter recorded the smallest value for every measured outcome."}, {"id": "C", "text": "Fish waste reversed the direction of the effect reported in the conclusion."}, {"id": "D", "text": "The data show no consistent relationship between the measured variables."}]'::jsonb, '{"type": "table", "caption": "Compost feedstock and finished-soil nitrogen", "headers": ["Feedstock", "N (mg/kg soil)"], "rows": [["Leaf litter", "710"], ["Fish waste", "1,905"], ["Coffee grounds", "1,480"], ["straw", "520"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-211', 'HDSAT-RW-INF-211', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'The figure summarizes a regional study on compost feedstock and finished-soil nitrogen.', 'Which statement is best supported by the data in the figure?', '[{"id": "A", "text": "The predictors are causally established by the summary figure alone, not merely correlated."}, {"id": "B", "text": "Leaf litter is the single most extreme value across all categories, dominating every comparison."}, {"id": "C", "text": "Every category differs from the next by the exact same margin, so no ranking is possible."}, {"id": "D", "text": "Fish waste (1,905 mg/kg) exceeds coffee grounds and both plant feedstocks."}]'::jsonb, '{"type": "line_chart", "caption": "Compost feedstock and finished-soil nitrogen", "x_label": "Feedstock", "y_label": "N (mg/kg soil)", "series": [{"label": "Leaf litter", "value": 710.0}, {"label": "Fish waste", "value": 1905.0}, {"label": "Coffee grounds", "value": 1480.0}, {"label": "straw", "value": 520.0}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.a