INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-300', 'HDSAT-RW-INF-300', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Beekeepers on the island of Aegina traditionally overwinter their hives above the thyme line at 300 meters, where the winter rains are heavier but the winds are calmer. Recent transit studies show that colonies moved down-slope for spring bloom return later to the thyme plateau because overnight cold snaps delay the first foraging flights.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Beekeepers now refuse to move colonies because transit studies are too new."}, {"id": "B", "text": "Moving hives down-slope for spring costs colonies foraging time because cold snaps at lower elevations delay the start of flying."}, {"id": "C", "text": "Thyme nectar on Aegina is most abundant in autumn when cold snaps end."}, {"id": "D", "text": "Aegina''s winds are strongest on the thyme plateau, which is why hives moved there."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-301', 'HDSAT-RW-INF-301', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Before the 1890s, Paris hotels removed carpets seasonally and washed them in the Seine. After the municipal water scheme of 1893, most hotels installed steam laundries that used half the water per rug, and the riverside carpet-washing wharves disappeared within a decade.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Steam laundries used more water per rug than the Seine wharves had."}, {"id": "B", "text": "The wharves were closed by ordinance following complaints about river pollution."}, {"id": "C", "text": "In-house steam laundries made riverside carpet washing economically obsolete."}, {"id": "D", "text": "Hotel operators could no longer transport carpets to the river after 1893."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-302', 'HDSAT-RW-INF-302', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Historian Noor Abdallah argues that eighteenth-century coffeehouse ledgers functioned as informal credit registries: because printers of the day listed debts alongside daily purchases, ordinary patrons could gauge a neighbor''s reputation simply by reading the wall.', 'Which quotation from a coffeehouse archive would most directly support Abdallah''s claim?', '[{"id": "A", "text": "“On the third shelf, under the chalk line, the ink still reads: ''Abed - two coffees, first paid Sunday last.''”"}, {"id": "B", "text": "“The proprietor whitewashed the doorstep each festival and replanted the mint by the door.”"}, {"id": "C", "text": "“Regulars gathered by the window to hear the news sheet read aloud each morning.”"}, {"id": "D", "text": "“Cocoa shipments from Batavia arrived quarterly and were stored in the cellar.”"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-303', 'HDSAT-RW-INF-303', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Popular retellings give Alexander Fleming sole credit for penicillin. Microbiologists often add that Howard Florey''s Oxford team purified the drug and ran the first clinical trials a decade later, and that the mass-production chemistry was solved in a Peoria laboratory using corn steep liquor.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It lists the equipment needed for antibiotic research without evaluating claims."}, {"id": "B", "text": "It compares two equally credited rival teams and declines to choose between them."}, {"id": "C", "text": "It counters a simplified account by adding the later research stages that turned a discovery into a medicine."}, {"id": "D", "text": "It narrates the chronological steps of one laboratory experiment in sequence."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-304', 'HDSAT-RW-INF-304', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1: Agronomist Isabel Ferro maintains that no-till farms build soil carbon fastest when residue from the previous grain crop is left standing; the stalks act as miniature snow fences that raise winter soil moisture.
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-305', 'HDSAT-RW-INF-305', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The 1911 catalog of the Balkan photographic cooperative lists its members as ''cartographers一枚, two schoolteachers, one pharmacist and a retired customs officer'', and advertises develop-and-return service in seven Balkan languages. Notably absent is any tariff for portraits.', 'What can most reasonably be inferred about the cooperative''s client base?', '[{"id": "A", "text": "It served a linguistically mixed rural trade whose commissions were mainly documentary rather than portraits."}, {"id": "B", "text": "Most clients commissioned formal portraits, which were priced by negotiation."}, {"id": "C", "text": "It relied on one dominant language, since developing was offered in seven scripts."}, {"id": "D", "text": "It sold equipment to professional portrait studios in the capital."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-306', 'HDSAT-RW-INF-306', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'The Saanich Inlet oxygen sensors deployed in 1958 recorded a six-decade decline in seafloor oxygen, interrupted by brief rebounds whenever strong El Nino winters flushed the basin.', 'According to the text, what causes rebounds in the sensor record?', '[{"id": "A", "text": "Strong El Nino winters that renew basin water."}, {"id": "B", "text": "Six decades of sediment accumulation on the seafloor."}, {"id": "C", "text": "Sensor upgrades that improved oxygen readings."}, {"id": "D", "text": "Declining seafloor temperature during El Nino years."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-307', 'HDSAT-RW-INF-307', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Rooftop apiaries are exempt from the city''s setback rules, and applicants may skip the soil test altogether when the apiary sits on a raised steel deck rather than on graded ground. Since 2019, 82 percent of permitted commercial hives have gone up on decks.', 'What can most reasonably be inferred from the passage?', '[{"id": "A", "text": "Setback exemptions apply only to hobbyists with fewer than two hives."}, {"id": "B", "text": "Most rooftop operators prefer soil-contact hives for flavor reasons."}, {"id": "C", "text": "For many operators, the avoided soil test makes decks the cheaper permitting path."}, {"id": "D", "text": "The city expects deck hives to fail more often than ground hives."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-308', 'HDSAT-RW-INF-308', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Wedgwood pattern books digitized in this study survive in two densities: the catalog volumes sent to retailers, which list glazes in flat but uniform decimals, and the workshop notebooks, which describe the same glazes fussily, with weather notes and batch quirks in the margins.', 'What does the text most directly suggest about the two kinds of records?', '[{"id": "A", "text": "Only the retailer catalogs record glaze chemistry accurately."}, {"id": "B", "text": "The workshop notebooks capture the variability that the standardized retailer catalogs smooth over."}, {"id": "C", "text": "Retailer catalogs were intended as internal training documents."}, {"id": "D", "text": "Notebook margins were later trimmed to match the catalogs'' decimals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-309', 'HDSAT-RW-INF-309', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Fifth-century shipwrights pegged planks with treenails cut from a single species: holm oak. timbers recovered from harbor silt, however, show the pegs'' grain aligned not with the trunk but spiraling with the branch. Replicas built either way show a two-fold difference in how often fasteners split the hull in heavy swell.', 'What can most reasonably be inferred?', '[{"id": "A", "text": "The two-fold difference appeared only when pegs were cut cross-grain."}, {"id": "B", "text": "Shipwrights tailored the cut of treenails to grain orientation because it dramatically affected fastener durability."}, {"id": "C", "text": "Holm oak branches were cheaper than trunks for all fifth-century construction."}, {"id": "D", "text": "Harbor silt preserved treenails more completely than other timbers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-310', 'HDSAT-RW-INF-310', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'In translation studies, ''domestication'' rewrites a foreign text into the target culture''s idioms, while ''foreignization'' preserves its strangeness. Reviewers of the 2023 Arabic edition of a Yup''ik oral history praised the translators for keeping names, pauses and mistranslation jokes intact, even where a domesticated version would have read more smoothly.', 'Which choice best states the main idea?', '[{"id": "A", "text": "Foreignization erases source-culture features like pauses and names."}, {"id": "B", "text": "The 2023 translators chose foreignization, retaining culture-specific features over smooth domesticated phrasing."}, {"id": "C", "text": "The Yup''ik oral history could not be translated into Arabic at all."}, {"id": "D", "text": "The reviewers demanded a second, domesticated edition for classroom use."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-311', 'HDSAT-RW-INF-311', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'In the 1920s, Cross Sound ferries had no schedule board; skippers whistled the crossing order to the dock crew. The practice continued until 1938, when a commissions clerk''s rotated daily notice board replaced the whistle both for reasons of record-keeping and because the clerk''s hearing had begun to fail.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "A problem-solution essay that evaluates competing whistle designs."}, {"id": "B", "text": "A chronological history of Pacific ferry technology from 1900 to the war."}, {"id": "C", "text": "An argumentative case that whistling was superior to posted schedules."}, {"id": "D", "text": "A narrative anecdote that closes by revealing the practical reason for the change."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-312', 'HDSAT-RW-INF-312', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Volunteers re-tagging the museum''s beetle drawers found that the 1930s card system grouped species by wing venation, while the glass collecting tubes above each tray held specimens gathered the same week that the tray was curated - apparently as unmatched ''bonus'' tips.', 'What does the passage most strongly suggest?', '[{"id": "A", "text": "The tubes were contributions tied to the curator''s weekly field visits rather than to the trays'' taxonomic scheme."}, {"id": "B", "text": "Tubes were part of the venation-centered card system''s key."}, {"id": "C", "text": "Weekly field trips were held by a separate volunteer committee."}, {"id": "D", "text": "The beetle drawers held no specimens at all until 1930."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-313', 'HDSAT-RW-INF-313', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Art historian Dana Cole contends that the 1915 Vienna sketches are by a student of the artist rather than the master, pointing to the habit of leaving the underdrawing visible wherever the pigment is thinnest.', 'Which quotation from a conservation lab report would most directly support Cole''s claim?', '[{"id": "A", "text": "“The sheet''s water-mark corresponds to a mill active in Vienna after 1900.”"}, {"id": "B", "text": "“Primer analysis matches the Vienna workshop''s orthodox chalk ground in every sample.”"}, {"id": "C", "text": "“Vermilion and viridian dominate both the master''s canvas and the studied sheet.”"}, {"id": "D", "text": "“Where the glaze has thinned to air, the graphite underdrawing remains fully legible, uncorrected by the artist''s usual opaque passages.”"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-314', 'HDSAT-RW-INF-314', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Ocean Genome Ledger archives discarded shipping-water samples alongside temperature and salinity logs so that species arriving in ballast can be reconstructed years later even after the water itself has been discharged.', 'According to the text, why are the environmental logs archived with the samples?', '[{"id": "A", "text": "So that later DNA work can be interpreted in the conditions the species actually arrived in."}, {"id": "B", "text": "Because discharge rules require water samples to be re-measured on land."}, {"id": "C", "text": "So the archive can sell paired logs at higher inspection prices."}, {"id": "D", "text": "Because salinity alone determines which species survive transit."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-315', 'HDSAT-RW-INF-315', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Critics of the 1930s radio soap operas dismissed them as formula-driven; media historians counter that several serials tested listener panels weekly and revised plots accordingly, an audience-analytics loop that network dayparts would not formalize for decades.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It narrates a single serial''s fall from popularity in three acts."}, {"id": "B", "text": "It compares two serials scene by scene and concludes that both fail."}, {"id": "C", "text": "It states a dismissal and then refutes it with evidence of a data-driven revision practice."}, {"id": "D", "text": "It defines ''daypart'' and traces the term''s usage over fifty years."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-316', 'HDSAT-RW-INF-316', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'The harbor authority''s new crane guide books list each wharf''s rated load in dry weather only, because steel augers lose grip once sustained rain raises the moisture film between auger and cladding.', 'According to the text, why do the guides list loads for dry weather only?', '[{"id": "A", "text": "Because rated loads are recalculated only with auger replacements."}, {"id": "B", "text": "Because moisture changes how firmly augers grip the wharf plating."}, {"id": "C", "text": "Because cranes are retired from service during rainy months."}, {"id": "D", "text": "Because rain makes the guide books'' paper unusable."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-317', 'HDSAT-RW-INF-317', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'When the city digitized permit filings in 2016, clerks retained the paper originals of the first month only; after that, applications arrived born-digital and the printing room was converted to a training space.', 'What can most reasonably be inferred from the passage?', '[{"id": "A", "text": "The printing room''s repurpose signals that paper permits had become production-obsolete."}, {"id": "B", "text": "The city had not actually digitized any filings before 2016."}, {"id": "C", "text": "Application volume declined sharply after the digitization project."}, {"id": "D", "text": "Clerks destroyed all permit records older than five years."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-318', 'HDSAT-RW-INF-318', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Curator Iris Belan argues that the gallery acquired its Etruscan mirror by gift rather than purchase, noting a 1974 accession ledger shows no prior valuation, which auction purchases require before clearance.', 'Which quotation from the registration files would most directly support Belan''s claim?', '[{"id": "A", "text": "“Cover letter dated 3 June 1974: ''I hope the museum will give it a home, as my father did in keeping it all these years.''”"}, {"id": "B", "text": "“Condition note records an old repair to the handle join, photographed in 1974.”"}, {"id": "C", "text": "“Insurance schedule for 1975 assigns the mirror a declared value in lire.”"}, {"id": "D", "text": "“Loan paperwork from 1968 lists the mirror as insured property of a private collection.”"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-319', 'HDSAT-RW-INF-319', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1: Nocturnist Omar Haddad writes that fall-prevention rounds at midnight are missing the point: большинстве falls happen at 5-6 a.m., so the fix is protecting the 5:30 medication walk, not adding midnight checks.
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-320', 'HDSAT-RW-INF-320', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Lighthouse keepers on the Atlantic coast were listed in federal payrolls, not in the mail-delivery rosters, even though several of them hand-carried mail between islands. In 1892, one keeper''s hand-carved mailboat chocks are preserved at the site museum to mark that informal service.', 'What is the purpose of the passage''s last sentence?', '[{"id": "A", "text": "To recount how the mailboat was lost in a storm."}, {"id": "B", "text": "To explain why federal rosters excluded mail duties."}, {"id": "C", "text": "To argue that keepers deserved both payroll listings."}, {"id": "D", "text": "To show a surviving object that documents the informal mail service described earlier."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-321', 'HDSAT-RW-INF-321', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The 1911 catalog of the Balkan photographic cooperative advertises develop-and-return service in seven languages. Its price list spans coin conditions from Pre-union Austrian to Bulgarian posts, and notably the only surcharge anywhere in the list is a winter carriage fee doubling delivery times to remote upland villages.', 'What can most reasonably be inferred about the cooperative''s deliveries?', '[{"id": "A", "text": "Language choice affected the base development price."}, {"id": "B", "text": "Remote upland orders were accepted but explicitly slower, with everything else priced uniformly."}, {"id": "C", "text": "Summer deliveries were surcharged like winter ones, just less visibly."}, {"id": "D", "text": "The cooperative refused upland orders during winter entirely."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-100', 'HDSAT-RW-CRF-100', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The committee''s report was unusually ______: every recommendation came with a cost estimate and a fallback plan.', 'Which choice completes the text with the most logical and precise word?', '[{"id": "A", "text": "adept"}, {"id": "B", "text": "blatant"}, {"id": "C", "text": "banish"}, {"id": "D", "text": "avid"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
