INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-57501', 'HDSAT-RW-INF-57501', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A regional hotel hospitality audit recorded the nightly rent (in USD) across four room categories, as shown in the graph (Survey #1).', 'According to the graph, which room type has the highest listed nightly rent?', '[{"id": "A", "text": "Courtyard Rooms"}, {"id": "B", "text": "Balcony Rooms"}, {"id": "C", "text": "Corner Suites"}, {"id": "D", "text": "Street-Facing Rooms"}]'::jsonb, '{"type": "bar_chart", "caption": "Hotel Survey #1: Nightly Rent by Room Type (USD)", "x_label": "Room Type", "y_label": "Nightly Rent (USD)", "series": [{"label": "Courtyard Rooms", "value": 24}, {"label": "Balcony Rooms", "value": 18}, {"label": "Street-Facing Rooms", "value": 40}, {"label": "Corner Suites", "value": 10}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-57502', 'HDSAT-RW-INF-57502', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'Hospitality researchers surveyed four room categories at a regional hotel and summarized the nightly rent and average occupancy in the table. Based on the survey, an analyst claimed: "Higher-rent room types earned the most revenue per available room in this survey."', 'Which finding from the table best supports the analyst''s claim?', '[{"id": "A", "text": "Street-Facing Rooms generated the highest revenue per available room (25 USD), consistent with the claimed relationship."}, {"id": "B", "text": "The survey tracked occupancy by season rather than by room type."}, {"id": "C", "text": "Occupancy percentages alone decide the claim without reference to rent."}, {"id": "D", "text": "Courtyard Rooms recorded the top rent, but the claim concerns per-room revenue, not rent alone."}]'::jsonb, '{"type": "table", "caption": "Hotel Survey #2: Room Rent and Average Nightly Occupancy", "headers": ["Room Type", "Nightly Rent (USD)", "Average Occupancy (%)"], "rows": [["Courtyard Rooms", "$36", "32%"], ["Balcony Rooms", "$27", "36%"], ["Street-Facing Rooms", "$60", "43%"], ["Corner Suites", "$15", "28%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-57503', 'HDSAT-RW-INF-57503', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A regional hotel hospitality audit recorded the nightly rent (in USD) across four room categories, as shown in the graph (Survey #3).', 'According to the graph, which room type has the highest listed nightly rent?', '[{"id": "A", "text": "Corner Suites"}, {"id": "B", "text": "Courtyard Rooms"}, {"id": "C", "text": "Street-Facing Rooms"}, {"id": "D", "text": "Balcony Rooms"}]'::jsonb, '{"type": "line_chart", "caption": "Hotel Survey #3: Nightly Rent by Room Type (USD)", "x_label": "Room Type", "y_label": "Nightly Rent (USD)", "series": [{"label": "Courtyard Rooms", "value": 48}, {"label": "Balcony Rooms", "value": 36}, {"label": "Street-Facing Rooms", "value": 80}, {"label": "Corner Suites", "value": 20}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
