INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-57537', 'HDSAT-RW-INF-57537', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A regional hotel hospitality audit recorded the nightly rent (in USD) across four room categories, as shown in the graph (Survey #37).', 'According to the graph, which room type has the highest listed nightly rent?', '[{"id": "A", "text": "Street-Facing Rooms"}, {"id": "B", "text": "Balcony Rooms"}, {"id": "C", "text": "Corner Suites"}, {"id": "D", "text": "Courtyard Rooms"}]'::jsonb, '{"type": "bar_chart", "caption": "Hotel Survey #37: Nightly Rent by Room Type (USD)", "x_label": "Room Type", "y_label": "Nightly Rent (USD)", "series": [{"label": "Courtyard Rooms", "value": 36}, {"label": "Balcony Rooms", "value": 27}, {"label": "Street-Facing Rooms", "value": 60}, {"label": "Corner Suites", "value": 15}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
