INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-57560', 'HDSAT-RW-INF-57560', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'Hospitality researchers surveyed four room categories at a regional hotel and summarized the nightly rent and average occupancy in the table. Based on the survey, an analyst claimed: "Higher-rent room types earned the most revenue per available room in this survey."', 'Which finding from the table best supports the analyst''s claim?', '[{"id": "A", "text": "Courtyard Rooms recorded the top rent, but the claim concerns per-room revenue, not rent alone."}, {"id": "B", "text": "Street-Facing Rooms generated the highest revenue per available room (41 USD), consistent with the claimed relationship."}, {"id": "C", "text": "Occupancy percentages alone decide the claim without reference to rent."}, {"id": "D", "text": "The survey tracked occupancy by season rather than by room type."}]'::jsonb, '{"type": "table", "caption": "Hotel Survey #60: Room Rent and Average Nightly Occupancy", "headers": ["Room Type", "Nightly Rent (USD)", "Average Occupancy (%)"], "rows": [["Courtyard Rooms", "$60", "30%"], ["Balcony Rooms", "$45", "34%"], ["Street-Facing Rooms", "$100", "41%"], ["Corner Suites", "$25", "26%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choi