INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88046', 'HDSAT-RW-CRF-88046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'In a recent study of drought-tolerant millet cultivars, the agricultural botanist compared subsoil moisture gradients from twelve independent field sites. Because every site recorded the same seasonal shift within a two-day margin, the new measurements ______ the team''s initial hypothesis rather than calling it into question.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "obscure"}, {"id": "B", "text": "repudiate"}, {"id": "C", "text": "corroborate"}, {"id": "D", "text": "fabricate"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88047', 'HDSAT-RW-CRF-88047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'When heavy rains overwhelm drought-tolerant millet cultivars, runoff can damage nearby infrastructure. To ______ these effects, the agricultural botanist recommended installing permeable buffers traced from subsoil moisture gradients, which absorb peak flows before they reach the main channel.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "perpetuate"}, {"id": "B", "text": "exacerbate"}, {"id": "C", "text": "instigate"}, {"id": "D", "text": "mitigate"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88048', 'HDSAT-RW-CRF-88048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Restoring drought-tolerant millet cultivars requires ______ attention to detail: the agricultural botanist spent four months cross-checking subsoil moisture gradients line by line so that not a single calibration error entered the published archive.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "nonchalant"}, {"id": "B", "text": "meticulous"}, {"id": "C", "text": "cursory"}, {"id": "D", "text": "haphazard"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88049', 'HDSAT-RW-CRF-88049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Unlike permanent stone markers, the phenomena documented in drought-tolerant millet cultivars are ______: as the agricultural botanist notes in subsoil moisture gradients, the surface patterns vanish within hours of forming and must be photographed immediately.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "ephemeral"}, {"id": "B", "text": "perennial"}, {"id": "C", "text": "immutable"}, {"id": "D", "text": "indelible"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88050', 'HDSAT-RW-CRF-88050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Faced with strict budget limits on drought-tolerant millet cultivars, the agricultural botanist set aside purely theoretical models and adopted a ______ approach grounded in subsoil moisture gradients, prioritizing repairs that could be completed with existing tools.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "quixotic"}, {"id": "B", "text": "pragmatic"}, {"id": "C", "text": "esoteric"}, {"id": "D", "text": "dogmatic"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88051', 'HDSAT-RW-CRF-88051', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Once considered rare outside specialized laboratories, instruments for monitoring drought-tolerant millet cultivars have become ______: according to subsoil moisture gradients compiled by the agricultural botanist, nearly every regional station now operates at least two units.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "sporadic"}, {"id": "B", "text": "ubiquitous"}, {"id": "C", "text": "vestigial"}, {"id": "D", "text": "anomalous"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88052', 'HDSAT-RW-CRF-88052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Although proponents expected subsoil moisture gradients to settle the debate over drought-tolerant millet cultivars, the agricultural botanist concluded that the findings remained ______, supporting two incompatible interpretations with nearly equal statistical weight.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "apodictic"}, {"id": "B", "text": "equivocal"}, {"id": "C", "text": "trenchant"}, {"id": "D", "text": "pellucid"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88053', 'HDSAT-RW-CRF-88053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Most variables in drought-tolerant millet cultivars responded predictably to standard adjustments, but one parameter proved ______: despite repeated recalibrations guided by subsoil moisture gradients, the agricultural botanist could not bring the outlier into alignment.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "compliant"}, {"id": "B", "text": "amenable"}, {"id": "C", "text": "tractable"}, {"id": "D", "text": "recalcitrant"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
