INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88089', 'HDSAT-RW-CRF-88089', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Most variables in ensemble staging notations responded predictably to standard adjustments, but one parameter proved ______: despite repeated recalibrations guided by asymmetrical rhythmic phrasing, the choreographer could not bring the outlier into alignment.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "tractable"}, {"id": "B", "text": "compliant"}, {"id": "C", "text": "recalcitrant"}, {"id": "D", "text": "amenable"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88090', 'HDSAT-RW-CRF-88090', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Among competing explanations of ensemble staging notations, the choreographer favored the most ______ model—one that accounted for all anomalies in asymmetrical rhythmic phrasing using only two variables instead of the seven required by earlier theories.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "profligate"}, {"id": "B", "text": "parsimonious"}, {"id": "C", "text": "circuitous"}, {"id": "D", "text": "redundant"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88201', 'HDSAT-RW-CRF-88201', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that estuarine oyster reefs serve only a single local function. However, recent analyses of sonar bathymetry logs demonstrate that estuarine oyster reefs play a decisive role in coastal wave attenuation, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two competing methodologies and argues that both are flawed."}, {"id": "B", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "C", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "D", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88202', 'HDSAT-RW-CRF-88202', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how estuarine oyster reefs contribute to coastal wave attenuation, researchers examined sonar bathymetry logs collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To explain the objective and evidentiary basis of a research effort involving estuarine oyster reefs."}, {"id": "B", "text": "To criticize regulators for delaying standards related to coastal wave attenuation."}, {"id": "C", "text": "To advocate for replacing estuarine oyster reefs with synthetic alternatives."}, {"id": "D", "text": "To prove that sonar bathymetry logs cannot be trusted without laboratory replication."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88203', 'HDSAT-RW-CRF-88203', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Early studies of estuarine oyster reefs relied on visual estimates that varied widely between observers. By contrast, contemporary teams use sonar bathymetry logs to quantify coastal wave attenuation with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It questions whether coastal wave attenuation can be measured by any existing instrument."}, {"id": "B", "text": "It provides a historical biography of the researchers who discovered estuarine oyster reefs."}, {"id": "C", "text": "It concedes that visual estimates remain superior to sonar bathymetry logs in most field settings."}, {"id": "D", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88204', 'HDSAT-RW-CRF-88204', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Although estuarine oyster reefs are frequently cited in discussions of coastal wave attenuation, few studies have isolated their effect from background climate variability. By pairing sonar bathymetry logs with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To summarize the career achievements of a leading specialist in estuarine oyster reefs."}, {"id": "B", "text": "To argue that background climate variability has no impact on coastal wave attenuation."}, {"id": "C", "text": "To list the financial costs of maintaining sonar bathymetry logs across multiple seasons."}, {"id": "D", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88205', 'HDSAT-RW-CRF-88205', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that coastal wave attenuation depends strictly on scale. Yet sonar bathymetry logs from estuarine oyster reefs reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "B", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}, {"id": "C", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "D", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in sonar bathymetry logs."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88206', 'HDSAT-RW-CRF-88206', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do estuarine oyster reefs sustain coastal wave attenuation under stresses that cause comparable systems to fail? The answer, recent sonar bathymetry logs suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}, {"id": "B", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "C", "text": "It warns policymakers against relying on sonar bathymetry logs when designing future infrastructure."}, {"id": "D", "text": "It refutes a popular misconception by demonstrating that estuarine oyster reefs fail more often than reported."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88207', 'HDSAT-RW-CRF-88207', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that early telegraph codebooks serve only a single local function. However, recent analyses of nineteenth-century tariff sheets demonstrate that early telegraph codebooks play a decisive role in commercial bandwidth compression, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "B", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}, {"id": "C", "text": "It compares two competing methodologies and argues that both are flawed."}, {"id": "D", "text": "It outlines a chronological sequence of events without evaluating their causes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88208', 'HDSAT-RW-CRF-88208', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how early telegraph codebooks contribute to commercial bandwidth compression, researchers examined nineteenth-century tariff sheets collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To explain the objective and evidentiary basis of a research effort involving early telegraph codebooks."}, {"id": "B", "text": "To criticize regulators for delaying standards related to commercial bandwidth compression."}, {"id": "C", "text": "To advocate for replacing early telegraph codebooks with synthetic alternatives."}, {"id": "D", "text": "To prove that nineteenth-century tariff sheets cannot be trusted without laboratory replication."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88209', 'HDSAT-RW-CRF-88209', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Early studies of early telegraph codebooks relied on visual estimates that varied widely between observers. By contrast, contemporary teams use nineteenth-century tariff sheets to quantify commercial bandwidth compression with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It provides a historical biography of the researchers who discovered early telegraph codebooks."}, {"id": "B", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "C", "text": "It concedes that visual estimates remain superior to nineteenth-century tariff sheets in most field settings."}, {"id": "D", "text": "It questions whether commercial bandwidth compression can be measured by any existing instrument."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.