INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88211', 'HDSAT-RW-CRF-88211', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that commercial bandwidth compression depends strictly on scale. Yet nineteenth-century tariff sheets from early telegraph codebooks reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "B", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "C", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}, {"id": "D", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in nineteenth-century tariff sheets."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, upd