INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88212', 'HDSAT-RW-CRF-88212', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do early telegraph codebooks sustain commercial bandwidth compression under stresses that cause comparable systems to fail? The answer, recent nineteenth-century tariff sheets suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It warns policymakers against relying on nineteenth-century tariff sheets when designing future infrastructure."}, {"id": "B", "text": "It refutes a popular misconception by demonstrating that early telegraph codebooks fail more often than reported."}, {"id": "C", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "D", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88213', 'HDSAT-RW-CRF-88213', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that high-altitude bristlecone pines serve only a single local function. However, recent analyses of tree-ring isotope ratios demonstrate that high-altitude bristlecone pines play a decisive role in multi-century drought reconstruction, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}, {"id": "B", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "C", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "D", "text": "It compares two competing methodologies and argues that both are flawed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88214', 'HDSAT-RW-CRF-88214', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how high-altitude bristlecone pines contribute to multi-century drought reconstruction, researchers examined tree-ring isotope ratios collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To prove that tree-ring isotope ratios cannot be trusted without laboratory replication."}, {"id": "B", "text": "To explain the objective and evidentiary basis of a research effort involving high-altitude bristlecone pines."}, {"id": "C", "text": "To criticize regulators for delaying standards related to multi-century drought reconstruction."}, {"id": "D", "text": "To advocate for replacing high-altitude bristlecone pines with synthetic alternatives."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88215', 'HDSAT-RW-CRF-88215', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of high-altitude bristlecone pines relied on visual estimates that varied widely between observers. By contrast, contemporary teams use tree-ring isotope ratios to quantify multi-century drought reconstruction with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It concedes that visual estimates remain superior to tree-ring isotope ratios in most field settings."}, {"id": "B", "text": "It provides a historical biography of the researchers who discovered high-altitude bristlecone pines."}, {"id": "C", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "D", "text": "It questions whether multi-century drought reconstruction can be measured by any existing instrument."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88216', 'HDSAT-RW-CRF-88216', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Although high-altitude bristlecone pines are frequently cited in discussions of multi-century drought reconstruction, few studies have isolated their effect from background climate variability. By pairing tree-ring isotope ratios with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To argue that background climate variability has no impact on multi-century drought reconstruction."}, {"id": "B", "text": "To list the financial costs of maintaining tree-ring isotope ratios across multiple seasons."}, {"id": "C", "text": "To summarize the career achievements of a leading specialist in high-altitude bristlecone pines."}, {"id": "D", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88217', 'HDSAT-RW-CRF-88217', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that multi-century drought reconstruction depends strictly on scale. Yet tree-ring isotope ratios from high-altitude bristlecone pines reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}, {"id": "B", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "C", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "D", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in tree-ring isotope ratios."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88218', 'HDSAT-RW-CRF-88218', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do high-altitude bristlecone pines sustain multi-century drought reconstruction under stresses that cause comparable systems to fail? The answer, recent tree-ring isotope ratios suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "B", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}, {"id": "C", "text": "It refutes a popular misconception by demonstrating that high-altitude bristlecone pines fail more often than reported."}, {"id": "D", "text": "It warns policymakers against relying on tree-ring isotope ratios when designing future infrastructure."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.s