INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88219', 'HDSAT-RW-CRF-88219', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that urban pocket parks serve only a single local function. However, recent analyses of infrared canopy thermography demonstrate that urban pocket parks play a decisive role in localized heat-island reduction, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "B", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "C", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}, {"id": "D", "text": "It compares two competing methodologies and argues that both are flawed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88220', 'HDSAT-RW-CRF-88220', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how urban pocket parks contribute to localized heat-island reduction, researchers examined infrared canopy thermography collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To prove that infrared canopy thermography cannot be trusted without laboratory replication."}, {"id": "B", "text": "To advocate for replacing urban pocket parks with synthetic alternatives."}, {"id": "C", "text": "To explain the objective and evidentiary basis of a research effort involving urban pocket parks."}, {"id": "D", "text": "To criticize regulators for delaying standards related to localized heat-island reduction."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88221', 'HDSAT-RW-CRF-88221', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of urban pocket parks relied on visual estimates that varied widely between observers. By contrast, contemporary teams use infrared canopy thermography to quantify localized heat-island reduction with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It provides a historical biography of the researchers who discovered urban pocket parks."}, {"id": "B", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "C", "text": "It concedes that visual estimates remain superior to infrared canopy thermography in most field settings."}, {"id": "D", "text": "It questions whether localized heat-island reduction can be measured by any existing instrument."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88222', 'HDSAT-RW-CRF-88222', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Although urban pocket parks are frequently cited in discussions of localized heat-island reduction, few studies have isolated their effect from background climate variability. By pairing infrared canopy thermography with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To summarize the career achievements of a leading specialist in urban pocket parks."}, {"id": "B", "text": "To argue that background climate variability has no impact on localized heat-island reduction."}, {"id": "C", "text": "To list the financial costs of maintaining infrared canopy thermography across multiple seasons."}, {"id": "D", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
