INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88224', 'HDSAT-RW-CRF-88224', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do urban pocket parks sustain localized heat-island reduction under stresses that cause comparable systems to fail? The answer, recent infrared canopy thermography suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "B", "text": "It refutes a popular misconception by demonstrating that urban pocket parks fail more often than reported."}, {"id": "C", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}, {"id": "D", "text": "It warns policymakers against relying on infrared canopy thermography when designing future infrastructure."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88225', 'HDSAT-RW-CRF-88225', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that medieval watermills serve only a single local function. However, recent analyses of manorial court rolls demonstrate that medieval watermills play a decisive role in regional grain-milling monopolies, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "B", "text": "It compares two competing methodologies and argues that both are flawed."}, {"id": "C", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "D", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88226', 'HDSAT-RW-CRF-88226', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how medieval watermills contribute to regional grain-milling monopolies, researchers examined manorial court rolls collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To advocate for replacing medieval watermills with synthetic alternatives."}, {"id": "B", "text": "To prove that manorial court rolls cannot be trusted without laboratory replication."}, {"id": "C", "text": "To explain the objective and evidentiary basis of a research effort involving medieval watermills."}, {"id": "D", "text": "To criticize regulators for delaying standards related to regional grain-milling monopolies."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88227', 'HDSAT-RW-CRF-88227', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of medieval watermills relied on visual estimates that varied widely between observers. By contrast, contemporary teams use manorial court rolls to quantify regional grain-milling monopolies with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It provides a historical biography of the researchers who discovered medieval watermills."}, {"id": "B", "text": "It questions whether regional grain-milling monopolies can be measured by any existing instrument."}, {"id": "C", "text": "It concedes that visual estimates remain superior to manorial court rolls in most field settings."}, {"id": "D", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88228', 'HDSAT-RW-CRF-88228', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Although medieval watermills are frequently cited in discussions of regional grain-milling monopolies, few studies have isolated their effect from background climate variability. By pairing manorial court rolls with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To list the financial costs of maintaining manorial court rolls across multiple seasons."}, {"id": "B", "text": "To summarize the career achievements of a leading specialist in medieval watermills."}, {"id": "C", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}, {"id": "D", "text": "To argue that background climate variability has no impact on regional grain-milling monopolies."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88229', 'HDSAT-RW-CRF-88229', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that regional grain-milling monopolies depends strictly on scale. Yet manorial court rolls from medieval watermills reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "B", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}, {"id": "C", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "D", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in manorial court rolls."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88230', 'HDSAT-RW-CRF-88230', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do medieval watermills sustain regional grain-milling monopolies under stresses that cause comparable systems to fail? The answer, recent manorial court rolls suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "B", "text": "It warns policymakers against relying on manorial court rolls when designing future infrastructure."}, {"id": "C", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}, {"id": "D", "text": "It refutes a popular misconception by demonstrating that medieval watermills fail more often than reported."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88231', 'HDSAT-RW-CRF-88231', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that migratory songbird stopovers serve only a single local function. However, recent analyses of banding station recapture records demonstrate that migratory songbird stopovers play a decisive role in spring phenology mismatches, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two competing methodologies and argues that both are flawed."}, {"id": "B", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "C", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "D", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88232', 'HDSAT-RW-CRF-88232', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how migratory songbird stopovers contribute to spring phenology mismatches, researchers examined banding station recapture records collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To explain the objective and evidentiary basis of a research effort involving migratory songbird stopovers."}, {"id": "B", "text": "To advocate for replacing migratory songbird stopovers with synthetic alternatives."}, {"id": "C", "text": "To prove that banding station recapture records cannot be trusted without laboratory replication."}, {"id": "D", "text": "To criticize regulators for delaying standards related to spring phenology mismatches."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88233', 'HDSAT-RW-CRF-88233', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of migratory songbird stopovers relied on visual estimates that varied widely between observers. By contrast, contemporary teams use banding station recapture records to quantify spring phenology mismatches with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It provides a historical biography of the researchers who discovered migratory songbird stopovers."}, {"id": "B", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "C", "text": "It concedes that visual estimates remain superior to banding station recapture records in most field settings."}, {"id": "D", "text": "It questions whether spring phenology mismatches can be measured by any existing instrument."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88234', 'HDSAT-RW-CRF-88234', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Although migratory songbird stopovers are frequently cited in discussions of spring phenology mismatches, few studies have isolated their effect from background climate variability. By pairing banding station recapture records with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To list the financial costs of maintaining banding station recapture records across multiple seasons."}, {"id": "B", "text": "To summarize the career achievements of a leading specialist in migratory songbird stopovers."}, {"id": "C", "text": "To argue that background climate variability has no impact on spring phenology mismatches."}, {"id": "D", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88235', 'HDSAT-RW-CRF-88235', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that spring phenology mismatches depends strictly on scale. Yet banding station recapture records from migratory songbird stopovers reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in banding station recapture records."}, {"id": "B", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "C", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "D", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88236', 'HDSAT-RW-CRF-88236', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do migratory songbird stopovers sustain spring phenology mismatches under stresses that cause comparable systems to fail? The answer, recent banding station recapture records suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "B", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}, {"id": "C", "text": "It refutes a popular misconception by demonstrating that migratory songbird stopovers fail more often than reported."}, {"id": "D", "text": "It warns policymakers against relying on banding station recapture records when designing future infrastructure."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDE