INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88237', 'HDSAT-RW-CRF-88237', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that vulcanized rubber seals serve only a single local function. However, recent analyses of hydrostatic chamber trials demonstrate that vulcanized rubber seals play a decisive role in deep-sea submersible pressure tolerances, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}, {"id": "B", "text": "It compares two competing methodologies and argues that both are flawed."}, {"id": "C", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "D", "text": "It outlines a chronological sequence of events without evaluating their causes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88238', 'HDSAT-RW-CRF-88238', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how vulcanized rubber seals contribute to deep-sea submersible pressure tolerances, researchers examined hydrostatic chamber trials collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To prove that hydrostatic chamber trials cannot be trusted without laboratory replication."}, {"id": "B", "text": "To explain the objective and evidentiary basis of a research effort involving vulcanized rubber seals."}, {"id": "C", "text": "To criticize regulators for delaying standards related to deep-sea submersible pressure tolerances."}, {"id": "D", "text": "To advocate for replacing vulcanized rubber seals with synthetic alternatives."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88239', 'HDSAT-RW-CRF-88239', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of vulcanized rubber seals relied on visual estimates that varied widely between observers. By contrast, contemporary teams use hydrostatic chamber trials to quantify deep-sea submersible pressure tolerances with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "B", "text": "It questions whether deep-sea submersible pressure tolerances can be measured by any existing instrument."}, {"id": "C", "text": "It provides a historical biography of the researchers who discovered vulcanized rubber seals."}, {"id": "D", "text": "It concedes that visual estimates remain superior to hydrostatic chamber trials in most field settings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88240', 'HDSAT-RW-CRF-88240', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Although vulcanized rubber seals are frequently cited in discussions of deep-sea submersible pressure tolerances, few studies have isolated their effect from background climate variability. By pairing hydrostatic chamber trials with control plots, a new investigation separates these factors for the first time.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To argue that background climate variability has no impact on deep-sea submersible pressure tolerances."}, {"id": "B", "text": "To highlight a methodological limitation in prior work and note how a new study addresses it."}, {"id": "C", "text": "To list the financial costs of maintaining hydrostatic chamber trials across multiple seasons."}, {"id": "D", "text": "To summarize the career achievements of a leading specialist in vulcanized rubber seals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88241', 'HDSAT-RW-CRF-88241', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Proponents of standard models claim that deep-sea submersible pressure tolerances depends strictly on scale. Yet hydrostatic chamber trials from vulcanized rubber seals reveal that micro-structural arrangement—not total size—governs performance, forcing theorists to revise the foundational equations of the field.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It summarizes a prevailing theoretical claim and then presents empirical findings that compel a revision of that claim."}, {"id": "B", "text": "It reconciles two seemingly contradictory datasets by showing both were miscalculated."}, {"id": "C", "text": "It traces the etymology of a scientific term before proposing a new classification system."}, {"id": "D", "text": "Itcelebrates a traditional hypothesis while dismissing recent anomalies in hydrostatic chamber trials."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88242', 'HDSAT-RW-CRF-88242', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Why do vulcanized rubber seals sustain deep-sea submersible pressure tolerances under stresses that cause comparable systems to fail? The answer, recent hydrostatic chamber trials suggest, lies not in raw material strength but in a self-correcting feedback loop that redistributes load before fractures can propagate.', 'Which choice best describes the rhetorical strategy of the text?', '[{"id": "A", "text": "It refutes a popular misconception by demonstrating that vulcanized rubber seals fail more often than reported."}, {"id": "B", "text": "It contrasts two historical eras of engineering without reaching a conclusion."}, {"id": "C", "text": "It warns policymakers against relying on hydrostatic chamber trials when designing future infrastructure."}, {"id": "D", "text": "It poses a puzzling question about system resilience and then resolves it using recent empirical evidence."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88243', 'HDSAT-RW-CRF-88243', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Many observers assume that cooperative seed libraries serve only a single local function. However, recent analyses of seasonal germination audits demonstrate that cooperative seed libraries play a decisive role in heirloom crop genetic diversity, reshaping how specialists evaluate the system as a whole.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines a technical term and then illustrates it with a fictional anecdote."}, {"id": "B", "text": "It outlines a chronological sequence of events without evaluating their causes."}, {"id": "C", "text": "It introduces a common assumption and then presents evidence that broadens that view."}, {"id": "D", "text": "It compares two competing methodologies and argues that both are flawed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88244', 'HDSAT-RW-CRF-88244', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'To understand how cooperative seed libraries contribute to heirloom crop genetic diversity, researchers examined seasonal germination audits collected over a ten-year period. Their primary goal was to establish a reliable baseline before new regulatory standards took effect.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To explain the objective and evidentiary basis of a research effort involving cooperative seed libraries."}, {"id": "B", "text": "To advocate for replacing cooperative seed libraries with synthetic alternatives."}, {"id": "C", "text": "To prove that seasonal germination audits cannot be trusted without laboratory replication."}, {"id": "D", "text": "To criticize regulators for delaying standards related to heirloom crop genetic diversity."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88245', 'HDSAT-RW-CRF-88245', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early studies of cooperative seed libraries relied on visual estimates that varied widely between observers. By contrast, contemporary teams use seasonal germination audits to quantify heirloom crop genetic diversity with millimeter precision, eliminating the subjective drift that plagued earlier surveys.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id": "A", "text": "It provides a historical biography of the researchers who discovered cooperative seed libraries."}, {"id": "B", "text": "It contrasts a modern measurement technique with the less reliable approach described in the first sentence."}, {"id": "C", "text": "It concedes that visual estimates remain superior to seasonal germination audits in most field settings."}, {"id": "D", "text": "It questions whether heirloom crop genetic diversity can be measured by any existing instrument."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribut