INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-88432', 'HDSAT-RW-CRF-88432', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88601', 'HDSAT-RW-INF-88601', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying Roman concrete harbor piers have long noted the presence of volcanic ash and lime. Detailed physical analyses now confirm that these features operate by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries. Consequently, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Roman concrete harbor piers perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "B", "text": "Researchers have been unable to determine how volcanic ash and lime functioned in historical settings."}, {"id": "C", "text": "Because seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time."}, {"id": "D", "text": "Roman concrete harbor piers were abandoned once modern synthetic substitutes became cheaper to manufacture."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88602', 'HDSAT-RW-INF-88602', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying Roman concrete harbor piers have long noted the presence of volcanic ash and lime. Detailed physical analyses now confirm that these features operate by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries. Consequently, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time.', 'According to the text, what specific role do volcanic ash and lime play in Roman concrete harbor piers?', '[{"id": "A", "text": "They prevent Roman concrete harbor piers from interacting with surrounding moisture or air currents."}, {"id": "B", "text": "They function by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries."}, {"id": "C", "text": "They serve primarily as decorative markers rather than functional components."}, {"id": "D", "text": "They reduce the lifespan of Roman concrete harbor piers by accelerating surface wear."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88603', 'HDSAT-RW-INF-88603', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying Roman concrete harbor piers have long noted the presence of volcanic ash and lime. Detailed physical analyses now confirm that these features operate by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries. Consequently, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time.', 'Which detail from the text best explains why Roman concrete harbor piers are effective?', '[{"id": "A", "text": "The fact that Roman concrete harbor piers require continuous human recalibration every hour."}, {"id": "B", "text": "The reliance on volcanic ash and lime, which work by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries."}, {"id": "C", "text": "A recent regulatory ban on modifying Roman concrete harbor piers without laboratory approval."}, {"id": "D", "text": "The complete absence of volcanic ash and lime in comparable systems from neighboring regions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88604', 'HDSAT-RW-INF-88604', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying Roman concrete harbor piers have long noted the presence of volcanic ash and lime. Detailed physical analyses now confirm that these features operate by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries. Consequently, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Historical records prove that Roman concrete harbor piers were copied from twentieth-century industrial blueprints."}, {"id": "B", "text": "Investigations of Roman concrete harbor piers show that exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time."}, {"id": "C", "text": "Field tests confirm that Roman concrete harbor piers operate only in laboratory vacuum chambers."}, {"id": "D", "text": "Studies of Roman concrete harbor piers indicate that volcanic ash and lime are largely ornamental and can be removed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88605', 'HDSAT-RW-INF-88605', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying Roman concrete harbor piers have long noted the presence of volcanic ash and lime. Detailed physical analyses now confirm that these features operate by seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries. Consequently, exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time.', 'Based on the text, what would most likely happen if Roman concrete harbor piers lacked volcanic ash and lime?', '[{"id": "A", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "B", "text": "Surrounding environments would immediately convert Roman concrete harbor piers into crystalline stone."}, {"id": "C", "text": "Observers would be unable to distinguish Roman concrete harbor piers from modern electronic sensors."}, {"id": "D", "text": "The mechanism of seawater dissolves the ash to grow interlocking aluminum-tobermorite crystals that reinforce micro-cracks over centuries would fail, preventing the system from achieving the outcome whereby exposure to seawater triggers crystal growth that strengthens Roman harbor concrete over time."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88606', 'HDSAT-RW-INF-88606', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying high-Andean Polylepis forests have long noted the presence of gnarled bark layers. Detailed physical analyses now confirm that these features operate by trapping nocturnal cloud moisture and insulating trunk tissue against nightly sub-zero freezes above 4,000 meters. Consequently, specialized bark structure enables Polylepis trees to retain moisture and survive extreme high-altitude cold.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Researchers have been unable to determine how gnarled bark layers functioned in historical settings."}, {"id": "B", "text": "high-Andean Polylepis forests were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "C", "text": "high-Andean Polylepis forests perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "D", "text": "Because trapping nocturnal cloud moisture and insulating trunk tissue against nightly sub-zero freezes above 4,000 meters, specialized bark structure enables Polylepis trees to retain moisture and survive extreme high-altitude cold."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88607', 'HDSAT-RW-INF-88607', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying high-Andean Polylepis forests have long noted the presence of gnarled bark layers. Detailed physical analyses now confirm that these features operate by trapping nocturnal cloud moisture and insulating trunk tissue against nightly sub-zero freezes above 4,000 meters. Consequently, specialized bark structure enables Polylepis trees to retain moisture and survive extreme high-altitude cold.', 'According to the text, what specific role do gnarled bark layers play in high-Andean Polylepis forests?', '[{"id": "A", "text": "They serve primarily as decorative markers rather than functional components."}, {"id": "B", "text": "They reduce the lifespan of high-Andean Polylepis forests by accelerating surface wear."}, {"id": "C", "text": "They prevent high-Andean Polylepis forests from interacting with surrounding moisture or air currents."}, {"id": "D", "text": "They function by trapping nocturnal cloud moisture and insulating trunk tissue against nightly sub-zero freezes above 4,000 meters."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source