INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88612', 'HDSAT-RW-INF-88612', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying nineteenth-century lighthouse Fresnel lenses have long noted the presence of concentric stepped glass prisms. Detailed physical analyses now confirm that these features operate by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore. Consequently, stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight.', 'According to the text, what specific role do concentric stepped glass prisms play in nineteenth-century lighthouse Fresnel lenses?', '[{"id": "A", "text": "They serve primarily as decorative markers rather than functional components."}, {"id": "B", "text": "They reduce the lifespan of nineteenth-century lighthouse Fresnel lenses by accelerating surface wear."}, {"id": "C", "text": "They prevent nineteenth-century lighthouse Fresnel lenses from interacting with surrounding moisture or air currents."}, {"id": "D", "text": "They function by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices