INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88613', 'HDSAT-RW-INF-88613', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying nineteenth-century lighthouse Fresnel lenses have long noted the presence of concentric stepped glass prisms. Detailed physical analyses now confirm that these features operate by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore. Consequently, stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight.', 'Which detail from the text best explains why nineteenth-century lighthouse Fresnel lenses are effective?', '[{"id": "A", "text": "The fact that nineteenth-century lighthouse Fresnel lenses require continuous human recalibration every hour."}, {"id": "B", "text": "The reliance on concentric stepped glass prisms, which work by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore."}, {"id": "C", "text": "The complete absence of concentric stepped glass prisms in comparable systems from neighboring regions."}, {"id": "D", "text": "A recent regulatory ban on modifying nineteenth-century lighthouse Fresnel lenses without laboratory approval."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prom