INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88614', 'HDSAT-RW-INF-88614', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying nineteenth-century lighthouse Fresnel lenses have long noted the presence of concentric stepped glass prisms. Detailed physical analyses now confirm that these features operate by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore. Consequently, stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Investigations of nineteenth-century lighthouse Fresnel lenses show that stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight."}, {"id": "B", "text": "Field tests confirm that nineteenth-century lighthouse Fresnel lenses operate only in laboratory vacuum chambers."}, {"id": "C", "text": "Historical records prove that nineteenth-century lighthouse Fresnel lenses were copied from twentieth-century industrial blueprints."}, {"id": "D", "text": "Studies of nineteenth-century lighthouse Fresnel lenses indicate that concentric stepped glass prisms are largely ornamental and can be removed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format =