INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88615', 'HDSAT-RW-INF-88615', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying nineteenth-century lighthouse Fresnel lenses have long noted the presence of concentric stepped glass prisms. Detailed physical analyses now confirm that these features operate by bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore. Consequently, stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight.', 'Based on the text, what would most likely happen if nineteenth-century lighthouse Fresnel lenses lacked concentric stepped glass prisms?', '[{"id": "A", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "B", "text": "The mechanism of bending oblique light rays into a single horizontal beam visible more than twenty nautical miles offshore would fail, preventing the system from achieving the outcome whereby stepped prism rings allowed Fresnel lenses to concentrate light into a far-reaching beam without excessive weight."}, {"id": "C", "text": "Surrounding environments would immediately convert nineteenth-century lighthouse Fresnel lenses into crystalline stone."}, {"id": "D", "text": "Observers would be unable to distinguish nineteenth-century lighthouse Fresnel lenses from modern electronic sensors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXC