INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88616', 'HDSAT-RW-INF-88616', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying subterranean termite ventilation mounds have long noted the presence of solar-heated outer chimneys. Detailed physical analyses now confirm that these features operate by driving convective air currents that flush carbon dioxide from deep brood chambers without mechanical fans. Consequently, temperature differences across mound walls power passive air circulation for the underground colony.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Because driving convective air currents that flush carbon dioxide from deep brood chambers without mechanical fans, temperature differences across mound walls power passive air circulation for the underground colony."}, {"id": "B", "text": "subterranean termite ventilation mounds were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "C", "text": "subterranean termite ventilation mounds perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "D", "text": "Researchers have been unable to determine how solar-heated outer chimneys functioned in historical settings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt =