INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88619', 'HDSAT-RW-INF-88619', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying subterranean termite ventilation mounds have long noted the presence of solar-heated outer chimneys. Detailed physical analyses now confirm that these features operate by driving convective air currents that flush carbon dioxide from deep brood chambers without mechanical fans. Consequently, temperature differences across mound walls power passive air circulation for the underground colony.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Historical records prove that subterranean termite ventilation mounds were copied from twentieth-century industrial blueprints."}, {"id": "B", "text": "Investigations of subterranean termite ventilation mounds show that temperature differences across mound walls power passive air circulation for the underground colony."}, {"id": "C", "text": "Studies of subterranean termite ventilation mounds indicate that solar-heated outer chimneys are largely ornamental and can be removed."}, {"id": "D", "text": "Field tests confirm that subterranean termite ventilation mounds operate only in laboratory vacuum chambers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXC