INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88620', 'HDSAT-RW-INF-88620', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying subterranean termite ventilation mounds have long noted the presence of solar-heated outer chimneys. Detailed physical analyses now confirm that these features operate by driving convective air currents that flush carbon dioxide from deep brood chambers without mechanical fans. Consequently, temperature differences across mound walls power passive air circulation for the underground colony.', 'Based on the text, what would most likely happen if subterranean termite ventilation mounds lacked solar-heated outer chimneys?', '[{"id": "A", "text": "The mechanism of driving convective air currents that flush carbon dioxide from deep brood chambers without mechanical fans would fail, preventing the system from achieving the outcome whereby temperature differences across mound walls power passive air circulation for the underground colony."}, {"id": "B", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "C", "text": "Surrounding environments would immediately convert subterranean termite ventilation mounds into crystalline stone."}, {"id": "D", "text": "Observers would be unable to distinguish subterranean termite ventilation mounds from modern electronic sensors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLU