INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88621', 'HDSAT-RW-INF-88621', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying Early Modern Dutch fluyt cargo ships have long noted the presence of pear-shaped hull cross-sections. Detailed physical analyses now confirm that these features operate by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties. Consequently, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Early Modern Dutch fluyt cargo ships perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "B", "text": "Early Modern Dutch fluyt cargo ships were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "C", "text": "Researchers have been unable to determine how pear-shaped hull cross-sections functioned in historical settings."}, {"id": "D", "text": "Because maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EX