INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88622', 'HDSAT-RW-INF-88622', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying Early Modern Dutch fluyt cargo ships have long noted the presence of pear-shaped hull cross-sections. Detailed physical analyses now confirm that these features operate by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties. Consequently, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments.', 'According to the text, what specific role do pear-shaped hull cross-sections play in Early Modern Dutch fluyt cargo ships?', '[{"id": "A", "text": "They reduce the lifespan of Early Modern Dutch fluyt cargo ships by accelerating surface wear."}, {"id": "B", "text": "They serve primarily as decorative markers rather than functional components."}, {"id": "C", "text": "They prevent Early Modern Dutch fluyt cargo ships from interacting with surrounding moisture or air currents."}, {"id": "D", "text": "They function by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata =