INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88623', 'HDSAT-RW-INF-88623', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying Early Modern Dutch fluyt cargo ships have long noted the presence of pear-shaped hull cross-sections. Detailed physical analyses now confirm that these features operate by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties. Consequently, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments.', 'Which detail from the text best explains why Early Modern Dutch fluyt cargo ships are effective?', '[{"id": "A", "text": "A recent regulatory ban on modifying Early Modern Dutch fluyt cargo ships without laboratory approval."}, {"id": "B", "text": "The reliance on pear-shaped hull cross-sections, which work by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties."}, {"id": "C", "text": "The complete absence of pear-shaped hull cross-sections in comparable systems from neighboring regions."}, {"id": "D", "text": "The fact that Early Modern Dutch fluyt cargo ships require continuous human recalibration every hour."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88624', 'HDSAT-RW-INF-88624', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying Early Modern Dutch fluyt cargo ships have long noted the presence of pear-shaped hull cross-sections. Detailed physical analyses now confirm that these features operate by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties. Consequently, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Historical records prove that Early Modern Dutch fluyt cargo ships were copied from twentieth-century industrial blueprints."}, {"id": "B", "text": "Field tests confirm that Early Modern Dutch fluyt cargo ships operate only in laboratory vacuum chambers."}, {"id": "C", "text": "Investigations of Early Modern Dutch fluyt cargo ships show that the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments."}, {"id": "D", "text": "Studies of Early Modern Dutch fluyt cargo ships indicate that pear-shaped hull cross-sections are largely ornamental and can be removed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88625', 'HDSAT-RW-INF-88625', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying Early Modern Dutch fluyt cargo ships have long noted the presence of pear-shaped hull cross-sections. Detailed physical analyses now confirm that these features operate by maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties. Consequently, the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments.', 'Based on the text, what would most likely happen if Early Modern Dutch fluyt cargo ships lacked pear-shaped hull cross-sections?', '[{"id": "A", "text": "Surrounding environments would immediately convert Early Modern Dutch fluyt cargo ships into crystalline stone."}, {"id": "B", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "C", "text": "The mechanism of maximizing hold volume below deck while minimizing the upper-deck width used by port authorities to assess toll duties would fail, preventing the system from achieving the outcome whereby the fluyt''s narrow upper deck and wide hold increased cargo capacity while reducing tax assessments."}, {"id": "D", "text": "Observers would be unable to distinguish Early Modern Dutch fluyt cargo ships from modern electronic sensors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88626', 'HDSAT-RW-INF-88626', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying desert fog-basking beetles have long noted the presence of alternating hydrophilic and waxy wing bumps. Detailed physical analyses now confirm that these features operate by condensing wind-blown coastal mist into droplets that roll directly toward the insect''s mouthparts. Consequently, microscopic surface patterns on the beetle''s back harvest drinking water from airborne fog.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "desert fog-basking beetles perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "B", "text": "Researchers have been unable to determine how alternating hydrophilic and waxy wing bumps functioned in historical settings."}, {"id": "C", "text": "Because condensing wind-blown coastal mist into droplets that roll directly toward the insect''s mouthparts, microscopic surface patterns on the beetle''s back harvest drinking water from airborne fog."}, {"id": "D", "text": "desert fog-basking beetles were abandoned once modern synthetic substitutes became cheaper to manufacture."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.