INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88630', 'HDSAT-RW-INF-88630', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying desert fog-basking beetles have long noted the presence of alternating hydrophilic and waxy wing bumps. Detailed physical analyses now confirm that these features operate by condensing wind-blown coastal mist into droplets that roll directly toward the insect''s mouthparts. Consequently, microscopic surface patterns on the beetle''s back harvest drinking water from airborne fog.', 'Based on the text, what would most likely happen if desert fog-basking beetles lacked alternating hydrophilic and waxy wing bumps?', '[{"id": "A", "text": "The mechanism of condensing wind-blown coastal mist into droplets that roll directly toward the insect''s mouthparts would fail, preventing the system from achieving the outcome whereby microscopic surface patterns on the beetle''s back harvest drinking water from airborne fog."}, {"id": "B", "text": "Surrounding environments would immediately convert desert fog-basking beetles into crystalline stone."}, {"id": "C", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "D", "text": "Observers would be unable to distinguish desert fog-basking beetles from modern electronic sensors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, forma