INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88631', 'HDSAT-RW-INF-88631', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying Renaissance Venetian glassmakers on Murano have long noted the presence of manganese dioxide additives. Detailed physical analyses now confirm that these features operate by neutralizing the greenish tint caused by iron impurities in river sand to yield crystal-clear cristallo vessels. Consequently, chemical decolorizers allowed Murano artisans to produce transparent glass from iron-bearing sand.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Renaissance Venetian glassmakers on Murano were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "B", "text": "Because neutralizing the greenish tint caused by iron impurities in river sand to yield crystal-clear cristallo vessels, chemical decolorizers allowed Murano artisans to produce transparent glass from iron-bearing sand."}, {"id": "C", "text": "Renaissance Venetian glassmakers on Murano perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "D", "text": "Researchers have been unable to determine how manganese dioxide additives functioned in historical settings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.sti