INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88635', 'HDSAT-RW-INF-88635', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying Renaissance Venetian glassmakers on Murano have long noted the presence of manganese dioxide additives. Detailed physical analyses now confirm that these features operate by neutralizing the greenish tint caused by iron impurities in river sand to yield crystal-clear cristallo vessels. Consequently, chemical decolorizers allowed Murano artisans to produce transparent glass from iron-bearing sand.', 'Based on the text, what would most likely happen if Renaissance Venetian glassmakers on Murano lacked manganese dioxide additives?', '[{"id": "A", "text": "The mechanism of neutralizing the greenish tint caused by iron impurities in river sand to yield crystal-clear cristallo vessels would fail, preventing the system from achieving the outcome whereby chemical decolorizers allowed Murano artisans to produce transparent glass from iron-bearing sand."}, {"id": "B", "text": "Observers would be unable to distinguish Renaissance Venetian glassmakers on Murano from modern electronic sensors."}, {"id": "C", "text": "Surrounding environments would immediately convert Renaissance Venetian glassmakers on Murano into crystalline stone."}, {"id": "D", "text": "The system would operate at twice its normal efficiency due to reduced weight."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88636', 'HDSAT-RW-INF-88636', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying boreal beaver meadow complexes have long noted the presence of abandoned multi-tiered timber dams. Detailed physical analyses now confirm that these features operate by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs. Consequently, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "boreal beaver meadow complexes were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "B", "text": "Because slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment."}, {"id": "C", "text": "boreal beaver meadow complexes perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "D", "text": "Researchers have been unable to determine how abandoned multi-tiered timber dams functioned in historical settings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88637', 'HDSAT-RW-INF-88637', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying boreal beaver meadow complexes have long noted the presence of abandoned multi-tiered timber dams. Detailed physical analyses now confirm that these features operate by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs. Consequently, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment.', 'According to the text, what specific role do abandoned multi-tiered timber dams play in boreal beaver meadow complexes?', '[{"id": "A", "text": "They function by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs."}, {"id": "B", "text": "They prevent boreal beaver meadow complexes from interacting with surrounding moisture or air currents."}, {"id": "C", "text": "They reduce the lifespan of boreal beaver meadow complexes by accelerating surface wear."}, {"id": "D", "text": "They serve primarily as decorative markers rather than functional components."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_meta