INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88638', 'HDSAT-RW-INF-88638', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying boreal beaver meadow complexes have long noted the presence of abandoned multi-tiered timber dams. Detailed physical analyses now confirm that these features operate by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs. Consequently, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment.', 'Which detail from the text best explains why boreal beaver meadow complexes are effective?', '[{"id": "A", "text": "The complete absence of abandoned multi-tiered timber dams in comparable systems from neighboring regions."}, {"id": "B", "text": "The reliance on abandoned multi-tiered timber dams, which work by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs."}, {"id": "C", "text": "The fact that boreal beaver meadow complexes require continuous human recalibration every hour."}, {"id": "D", "text": "A recent regulatory ban on modifying boreal beaver meadow complexes without laboratory approval."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDE