INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88639', 'HDSAT-RW-INF-88639', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying boreal beaver meadow complexes have long noted the presence of abandoned multi-tiered timber dams. Detailed physical analyses now confirm that these features operate by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs. Consequently, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Investigations of boreal beaver meadow complexes show that beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment."}, {"id": "B", "text": "Studies of boreal beaver meadow complexes indicate that abandoned multi-tiered timber dams are largely ornamental and can be removed."}, {"id": "C", "text": "Field tests confirm that boreal beaver meadow complexes operate only in laboratory vacuum chambers."}, {"id": "D", "text": "Historical records prove that boreal beaver meadow complexes were copied from twentieth-century industrial blueprints."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLU