INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88640', 'HDSAT-RW-INF-88640', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying boreal beaver meadow complexes have long noted the presence of abandoned multi-tiered timber dams. Detailed physical analyses now confirm that these features operate by slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs. Consequently, beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment.', 'Based on the text, what would most likely happen if boreal beaver meadow complexes lacked abandoned multi-tiered timber dams?', '[{"id": "A", "text": "The mechanism of slowing snowmelt runoff and trapping organic silt that sustains wetland sedges decades after the colony departs would fail, preventing the system from achieving the outcome whereby beaver-engineered dam remnants continue to regulate water and build fertile meadow soils long after abandonment."}, {"id": "B", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "C", "text": "Observers would be unable to distinguish boreal beaver meadow complexes from modern electronic sensors."}, {"id": "D", "text": "Surrounding environments would immediately convert boreal beaver meadow complexes into crystalline stone."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, s