INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88641', 'HDSAT-RW-INF-88641', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying transatlantic submarine telegraph cables have long noted the presence of gutta-percha latex insulation. Detailed physical analyses now confirm that these features operate by maintaining electrical resistance under cold, high-pressure abyssal seawater where natural rubber rapidly degraded. Consequently, gutta-percha provided the durable underwater insulation needed for nineteenth-century ocean telegraphy.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "transatlantic submarine telegraph cables perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "B", "text": "transatlantic submarine telegraph cables were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "C", "text": "Researchers have been unable to determine how gutta-percha latex insulation functioned in historical settings."}, {"id": "D", "text": "Because maintaining electrical resistance under cold, high-pressure abyssal seawater where natural rubber rapidly degraded, gutta-percha provided the durable underwater insulation needed for nineteenth-century ocean telegraphy."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus 