INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88645', 'HDSAT-RW-INF-88645', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying transatlantic submarine telegraph cables have long noted the presence of gutta-percha latex insulation. Detailed physical analyses now confirm that these features operate by maintaining electrical resistance under cold, high-pressure abyssal seawater where natural rubber rapidly degraded. Consequently, gutta-percha provided the durable underwater insulation needed for nineteenth-century ocean telegraphy.', 'Based on the text, what would most likely happen if transatlantic submarine telegraph cables lacked gutta-percha latex insulation?', '[{"id": "A", "text": "The mechanism of maintaining electrical resistance under cold, high-pressure abyssal seawater where natural rubber rapidly degraded would fail, preventing the system from achieving the outcome whereby gutta-percha provided the durable underwater insulation needed for nineteenth-century ocean telegraphy."}, {"id": "B", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "C", "text": "Observers would be unable to distinguish transatlantic submarine telegraph cables from modern electronic sensors."}, {"id": "D", "text": "Surrounding environments would immediately convert transatlantic submarine telegraph cables into crystalline stone."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = 