INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88646', 'HDSAT-RW-INF-88646', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying ancient Persian qanat water channels have long noted the presence of gently sloped underground galleries. Detailed physical analyses now confirm that these features operate by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss. Consequently, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Because tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation."}, {"id": "B", "text": "ancient Persian qanat water channels were abandoned once modern synthetic substitutes became cheaper to manufacture."}, {"id": "C", "text": "ancient Persian qanat water channels perform poorly whenever ambient temperatures fluctuate by more than five degrees."}, {"id": "D", "text": "Researchers have been unable to determine how gently sloped underground galleries functioned in historical settings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88647', 'HDSAT-RW-INF-88647', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Specialists studying ancient Persian qanat water channels have long noted the presence of gently sloped underground galleries. Detailed physical analyses now confirm that these features operate by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss. Consequently, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation.', 'According to the text, what specific role do gently sloped underground galleries play in ancient Persian qanat water channels?', '[{"id": "A", "text": "They reduce the lifespan of ancient Persian qanat water channels by accelerating surface wear."}, {"id": "B", "text": "They serve primarily as decorative markers rather than functional components."}, {"id": "C", "text": "They prevent ancient Persian qanat water channels from interacting with surrounding moisture or air currents."}, {"id": "D", "text": "They function by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88648', 'HDSAT-RW-INF-88648', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying ancient Persian qanat water channels have long noted the presence of gently sloped underground galleries. Detailed physical analyses now confirm that these features operate by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss. Consequently, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation.', 'Which detail from the text best explains why ancient Persian qanat water channels are effective?', '[{"id": "A", "text": "A recent regulatory ban on modifying ancient Persian qanat water channels without laboratory approval."}, {"id": "B", "text": "The reliance on gently sloped underground galleries, which work by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss."}, {"id": "C", "text": "The fact that ancient Persian qanat water channels require continuous human recalibration every hour."}, {"id": "D", "text": "The complete absence of gently sloped underground galleries in comparable systems from neighboring regions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88649', 'HDSAT-RW-INF-88649', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Specialists studying ancient Persian qanat water channels have long noted the presence of gently sloped underground galleries. Detailed physical analyses now confirm that these features operate by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss. Consequently, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation.', 'Which choice best summarizes the central finding described in the text?', '[{"id": "A", "text": "Field tests confirm that ancient Persian qanat water channels operate only in laboratory vacuum chambers."}, {"id": "B", "text": "Historical records prove that ancient Persian qanat water channels were copied from twentieth-century industrial blueprints."}, {"id": "C", "text": "Investigations of ancient Persian qanat water channels show that subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation."}, {"id": "D", "text": "Studies of ancient Persian qanat water channels indicate that gently sloped underground galleries are largely ornamental and can be removed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88650', 'HDSAT-RW-INF-88650', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Specialists studying ancient Persian qanat water channels have long noted the presence of gently sloped underground galleries. Detailed physical analyses now confirm that these features operate by tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss. Consequently, subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation.', 'Based on the text, what would most likely happen if ancient Persian qanat water channels lacked gently sloped underground galleries?', '[{"id": "A", "text": "The mechanism of tapping upland alluvial aquifers and conveying water kilometers across arid plains with minimal evaporative loss would fail, preventing the system from achieving the outcome whereby subsurface gravity channels enabled arid settlements to transport groundwater without surface evaporation."}, {"id": "B", "text": "The system would operate at twice its normal efficiency due to reduced weight."}, {"id": "C", "text": "Surrounding environments would immediately convert ancient Persian qanat water channels into crystalline stone."}, {"id": "D", "text": "Observers would be unable to distinguish ancient Persian qanat water channels from modern electronic sensors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88801', 'HDSAT-RW-INF-88801', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'In a recent study, ornithologist Farah Al-Mansoor argues that urban blackbirds shift their dawn chorus to higher acoustic frequencies to avoid masking by low-frequency traffic rumble (dataset series 1).', 'Which finding from the research team''s records, if true, would most directly support ornithologist Farah Al-Mansoor''s claim?', '[{"id": "A", "text": "Plumage reflectance measurements did not differ significantly between urban and rural adult males."}, {"id": "B", "text": "Recordings from 40 city parks show an average minimum song frequency of 2.4 kHz, compared with 1.8 kHz in quiet rural forests 30 kilometers away."}, {"id": "C", "text": "Blackbirds in both city parks and rural forests begin singing approximately thirty minutes before civil sunrise."}, {"id": "D", "text": "Clutch sizes in suburban gardens averaged 4.1 eggs per nest across the three-year observation window."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.s