INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88802', 'HDSAT-RW-INF-88802', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'In a recent study, ornithologist Farah Al-Mansoor argues that urban blackbirds shift their dawn chorus to higher acoustic frequencies to avoid masking by low-frequency traffic rumble (dataset series 1).', 'Which quotation from a peer-reviewed report would most effectively illustrate ornithologist Farah Al-Mansoor''s hypothesis?', '[{"id": "A", "text": "Recordings from 40 city parks show an average minimum song frequency of 2.4 kHz, compared with 1.8 kHz in quiet rural forests 30 kilometers away."}, {"id": "B", "text": "Clutch sizes in suburban gardens averaged 4.1 eggs per nest across the three-year observation window."}, {"id": "C", "text": "Plumage reflectance measurements did not differ significantly between urban and rural adult males."}, {"id": "D", "text": "Blackbirds in both city parks and rural forests begin singing approximately thirty minutes before civil sunrise."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.st