INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88810', 'HDSAT-RW-INF-88810', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'In a recent study, economic historian Takeshi Sato argues that sixteenth-century regional fairs declined not because of wartime disruptions but because permanent urban exchanges lowered transaction verification costs (dataset series 1).', 'Which finding from the research team''s records, if true, would most directly support economic historian Takeshi Sato''s claim?', '[{"id": "A", "text": "Merchant correspondence from 1570–1590 repeatedly cites the ability to verify bills of exchange daily at Antwerp''s permanent bourse as the reason for skipping seasonal fairs."}, {"id": "B", "text": "Seasonal fairs continued to host popular theatrical performances well into the seventeenth century."}, {"id": "C", "text": "Gold coinage minted in Antwerp shared a uniform weight standard with coins from neighboring provinces."}, {"id": "D", "text": "Wartime tolls on river barges fluctuated between three and five percent during the 1560s."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution