INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88819', 'HDSAT-RW-INF-88819', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'In a recent study, plant physiologist Ingrid Lindholm argues that alpine cushion plants share carbon reserves across grafted root networks when neighbor shoots are shaded by late-lying snowbanks (dataset series 1).', 'Which finding from the research team''s records, if true, would most directly support plant physiologist Ingrid Lindholm''s claim?', '[{"id": "A", "text": "Isotope-labeled carbon introduced to sunlit perimeter stems appeared within 48 hours in the respiring root tips of fully snow-covered adjacent plants."}, {"id": "B", "text": "Alpine cushion species flower within ten days of snowmelt regardless of elevation."}, {"id": "C", "text": "Seed dispersal in high-alpine basins relies primarily on wind rather than insect vectors."}, {"id": "D", "text": "Soil temperatures beneath cushion mats remain two degrees warmer than bare scree slopes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
