INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88836', 'HDSAT-RW-INF-88836', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'In a recent study, archaeometallurgist Kwame Mensah argues that early Iron Age bloomery furnaces in West Africa achieved high-carbon steel directly through deliberate tuyere air-intake placement rather than post-forging carburization (dataset series 3).', 'Which empirical observation, if documented, would provide the strongest direct evidence for the mechanism archaeometallurgist Kwame Mensah proposes?', '[{"id": "A", "text": "Finished iron agricultural hoes were traded across distances exceeding four hundred kilometers."}, {"id": "B", "text": "Excavated furnace walls preserve angled clay blowpipes positioned to create a localized, oxygen-rich high-temperature zone that uniformly alloyed iron and carbon during the initial smelt."}, {"id": "C", "text": "Charcoal recovered from the slag heaps derived predominantly from slow-burning hardwood species."}, {"id": "D", "text": "Radiocarbon dates place the earliest furnace operations at the site in the sixth century BCE."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_n