INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88837', 'HDSAT-RW-INF-88837', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'In a recent study, cognitive psychologist Elena Morales argues that bilingual readers resolve syntactically ambiguous sentences faster when both languages share similar relative-clause attachment preferences (dataset series 1).', 'Which finding from the research team''s records, if true, would most directly support cognitive psychologist Elena Morales''s claim?', '[{"id": "A", "text": "Eye-tracking logs revealed 25% shorter regression fixations among Spanish-Italian bilinguals than among Spanish-English bilinguals on identical relative-clause test items."}, {"id": "B", "text": "Reading speed on unambiguous simple declarative sentences did not vary across language groups."}, {"id": "C", "text": "Self-reported daily reading hours correlated positively with overall working-memory span."}, {"id": "D", "text": "All participants completed a standardized vocabulary screening in less than twelve minutes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88838', 'HDSAT-RW-INF-88838', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'In a recent study, cognitive psychologist Elena Morales argues that bilingual readers resolve syntactically ambiguous sentences faster when both languages share similar relative-clause attachment preferences (dataset series 1).', 'Which quotation from a peer-reviewed report would most effectively illustrate cognitive psychologist Elena Morales''s hypothesis?', '[{"id": "A", "text": "Reading speed on unambiguous simple declarative sentences did not vary across language groups."}, {"id": "B", "text": "All participants completed a standardized vocabulary screening in less than twelve minutes."}, {"id": "C", "text": "Self-reported daily reading hours correlated positively with overall working-memory span."}, {"id": "D", "text": "Eye-tracking logs revealed 25% shorter regression fixations among Spanish-Italian bilinguals than among Spanish-English bilinguals on identical relative-clause test items."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, st