INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88845', 'HDSAT-RW-INF-88845', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'In a recent study, cognitive psychologist Elena Morales argues that bilingual readers resolve syntactically ambiguous sentences faster when both languages share similar relative-clause attachment preferences (dataset series 3).', 'Which empirical observation, if documented, would provide the strongest direct evidence for the mechanism cognitive psychologist Elena Morales proposes?', '[{"id": "A", "text": "All participants completed a standardized vocabulary screening in less than twelve minutes."}, {"id": "B", "text": "Eye-tracking logs revealed 25% shorter regression fixations among Spanish-Italian bilinguals than among Spanish-English bilinguals on identical relative-clause test items."}, {"id": "C", "text": "Reading speed on unambiguous simple declarative sentences did not vary across language groups."}, {"id": "D", "text": "Self-reported daily reading hours correlated positively with overall working-memory span."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = E