INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88903', 'HDSAT-RW-INF-88903', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'In a controlled trial of porous asphalt pavements, engineers found that void spaces clogged with fine silt within eighteen months on low-speed residential streets, whereas highways carrying 55-mile-per-hour traffic maintained 85% of their initial drainage capacity after five years without vacuum sweeping. (Series 1.) Taken together, the evidence implies that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "residential streets receive more annual rainfall than multi-lane highways do."}, {"id": "B", "text": "high-speed tire suction helps clear surface pores, making porous asphalt self-cleaning under fast traffic but maintenance-dependent on slow streets."}, {"id": "C", "text": "porous asphalt is structurally too weak to support highway truck loads."}, {"id": "D", "text": "vacuum sweeping reduces the drainage capacity of highway pavements."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
