status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88918', 'HDSAT-RW-INF-88918', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Archival guild rules from fourteenth-century Bruges prohibited dyers from keeping both woad (blue) and madder (red) vats in the same workshop, even though combining the two dyes was the standard method for producing luxury violet cloth. Separate ledger entries show that violet yardage nonetheless commanded the city''s highest export volume. (Series 3.) Taken together, the evidence implies that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "guild inspectors never enforced the workshop separation rule in practice."}, {"id": "B", "text": "madder and woad chemically neutralized each other whenever applied to wool."}, {"id": "C", "text": "Bruges cloth merchants coordinated production across specialized single-dye workshops rather than completing multi-stage dyeing under one roof."}, {"id": "D", "text": "fourteenth-century Bruges consumers refused to purchase blue or red garments."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, stat