INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88927', 'HDSAT-RW-INF-88927', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'When marine biologists transplanted cold-water corals from 600 meters depth to laboratory tanks matching deep-sea temperature and pressure, polyps fed only surface phytoplankton grew at one-third the rate of wild colonies, whereas polyps supplemented with resuspended seafloor detritus matched wild growth rates. (Series 3.) Taken together, the evidence implies that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "wild colonies at 600 meters depth experience warmer temperatures than surface waters."}, {"id": "B", "text": "deep-water coral colonies rely substantially on recycled benthic organic matter rather than fresh surface bloom fallout alone."}, {"id": "C", "text": "laboratory pressure chambers prevent coral polyps from extending their feeding tentacles."}, {"id": "D", "text": "cold-water corals require sunlight to photosynthesize their own nutrients."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, up