INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88928', 'HDSAT-RW-INF-88928', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'In early print shops, compositors pulled metal type letters from compartmentalized wooden cases without looking, relying on muscle memory. Bibliographers analyzing 1580s quartos noticed that spelling variants with extra silent ''e'' endings clustered exclusively near the bottom edge of full pages, where lines had to be justified tightly against the chase. (Series 1.) Therefore, it can be logically inferred that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "compositors ran out of metal ''e'' sorts before reaching the bottom of a page."}, {"id": "B", "text": "wooden type cases were rearranged daily to prevent compositors from memorizing letter positions."}, {"id": "C", "text": "sixteenth-century authors demanded strict, invariant spelling across every page of a manuscript."}, {"id": "D", "text": "compositors strategically inserted or omitted silent letters as a practical spacing tool to make lines fit evenly in the frame."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88929', 'HDSAT-RW-INF-88929', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In early print shops, compositors pulled metal type letters from compartmentalized wooden cases without looking, relying on muscle memory. Bibliographers analyzing 1580s quartos noticed that spelling variants with extra silent ''e'' endings clustered exclusively near the bottom edge of full pages, where lines had to be justified tightly against the chase. (Series 1.) Consequently, these observations suggest that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "compositors strategically inserted or omitted silent letters as a practical spacing tool to make lines fit evenly in the frame."}, {"id": "B", "text": "compositors ran out of metal ''e'' sorts before reaching the bottom of a page."}, {"id": "C", "text": "sixteenth-century authors demanded strict, invariant spelling across every page of a manuscript."}, {"id": "D", "text": "wooden type cases were rearranged daily to prevent compositors from memorizing letter positions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED