INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88943', 'HDSAT-RW-INF-88943', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'To test whether mycorrhizal fungi allocate phosphorus preferentially to productive host roots, botanists connected three separate root systems to a single fungal network and shaded two of the hosts. Within72 hours, phosphorus transfer to the unshaded, actively photosynthesizing host tripled, while transfer to the shaded hosts dropped by 70%. (Series 3.) Therefore, it can be logically inferred that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "shaded host plants absorb more phosphorus from the soil than sunlit plants do."}, {"id": "B", "text": "the fungal network directs mineral nutrients toward host plants that supply the most photosynthetic carbon in return."}, {"id": "C", "text": "phosphorus availability in the soil increases whenever canopy light levels decline."}, {"id": "D", "text": "mycorrhizal fungi sever all physical connections with host roots after 72 hours."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-88944', 'HDSAT-RW-INF-88944', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'To test whether mycorrhizal fungi allocate phosphorus preferentially to productive host roots, botanists connected three separate root systems to a single fungal network and shaded two of the hosts. Within72 hours, phosphorus transfer to the unshaded, actively photosynthesizing host tripled, while transfer to the shaded hosts dropped by 70%. (Series 3.) Consequently, these observations suggest that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "mycorrhizal fungi sever all physical connections with host roots after 72 hours."}, {"id": "B", "text": "phosphorus availability in the soil increases whenever canopy light levels decline."}, {"id": "C", "text": "the fungal network directs mineral nutrients toward host plants that supply the most photosynthetic carbon in return."}, {"id": "D", "text": "shaded host plants absorb more phosphorus from the soil than sunlit plants do."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
