INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89301', 'HDSAT-RW-SEC-89301', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The conservatory''s roof panes were cast from low-iron glass, ____ they transmitted ninety-two percent of winter sunlight.', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "whereas"}, {"id": "B", "text": "and"}, {"id": "C", "text": "however,"}, {"id": "D", "text": "; and"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89302', 'HDSAT-RW-SEC-89302', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'Because the conservatory''s roof panes were cast from low-iron glass, ____', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "; they transmitted ninety-two percent of winter sunlight."}, {"id": "B", "text": "and they transmitted ninety-two percent of winter sunlight."}, {"id": "C", "text": "they transmitted ninety-two percent of winter sunlight."}, {"id": "D", "text": "however, they transmitted ninety-two percent of winter sunlight."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89303', 'HDSAT-RW-SEC-89303', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The conservatory''s roof panes were cast from low-iron glass; ____', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "and they transmitted ninety-two percent of winter sunlight."}, {"id": "B", "text": ", they transmitted ninety-two percent of winter sunlight."}, {"id": "C", "text": "while they transmitted ninety-two percent of winter sunlight."}, {"id": "D", "text": "they transmitted ninety-two percent of winter sunlight."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89304', 'HDSAT-RW-SEC-89304', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The conservatory''s roof panes were cast from low-iron glass—a feature documented across three seasons—____', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "and, heating costs fell by a third."}, {"id": "B", "text": "; so heating costs fell by a third."}, {"id": "C", "text": "so heating costs fell by a third."}, {"id": "D", "text": "heating costs fell by a third."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89305', 'HDSAT-RW-SEC-89305', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'Having noted that the conservatory''s roof panes were cast from low-iron glass, the researchers observed a secondary effect____', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "—that they transmitted ninety-two percent of winter sunlight."}, {"id": "B", "text": "; they transmitted ninety-two percent of winter sunlight."}, {"id": "C", "text": ", they transmitted ninety-two percent of winter sunlight."}, {"id": "D", "text": ": they transmitted ninety-two percent of winter sunlight."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-89306', 'HDSAT-RW-SEC-89306', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'Although the conservatory''s roof panes were cast from low-iron glass, they transmitted ninety-two percent of winter sunlight____', 'Which choice completes the text so that it conforms to Standard English?', '[{"id": "A", "text": "; heating costs fell by a third, consequently."}, {"id": "B", "text": ", consequently, heating costs fell by a third."}, {"id": "C", "text": "; consequently, heating costs fell by a third."}, {"id": "D", "text": "—consequently heating costs fell by a third."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
