INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-LIF-116', 'C', ARRAY['C']::TEXT[], 'Slope $= \dfrac{18 - 2}{5 - 1} = \dfrac{16}{4} = 4$. Always check by substituting the given values or factoring back out.', '{"B": "Check: rising $4$ over a run of $4$ would not land on $(5, 18)$ from $(1, 2)$; recomputing the ratio gives 4.", "A": "Check: rising $4$ over a run of $4$ would not land on $(5, 18)$ from $(1, 2)$; recomputing the ratio gives 4.", "D": "Check: rising $4$ over a run of $4$ would not land on $(5, 18)$ from $(1, 2)$; recomputing the ratio gives 4."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
