INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-LIF-119', 'C', ARRAY['C']::TEXT[], 'Slope $= \dfrac{18 - -2}{7 - 3} = \dfrac{20}{4} = 5$. Always check by substituting the given values or factoring back out.', '{"D": "Check: rising $5$ over a run of $4$ would not land on $(7, 18)$ from $(3, -2)$; recomputing the ratio gives 5.", "A": "Check: rising $5$ over a run of $4$ would not land on $(7, 18)$ from $(3, -2)$; recomputing the ratio gives 5.", "B": "Check: rising $5$ over a run of $4$ would not land on $(7, 18)$ from $(3, -2)$; recomputing the ratio gives 5."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
