INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-LIF-121', 'A', ARRAY['A']::TEXT[], 'Slope $= \dfrac{-7 - 9}{6 - 2} = \dfrac{-16}{4} = -4$. Always check by substituting the given values or factoring back out.', '{"B": "Check: rising $4$ over a run of $4$ would not land on $(6, -7)$ from $(2, 9)$; recomputing the ratio gives -4.", "D": "Check: rising $4$ over a run of $4$ would not land on $(6, -7)$ from $(2, 9)$; recomputing the ratio gives -4.", "C": "Check: rising $4$ over a run of $4$ would not land on $(6, -7)$ from $(2, 9)$; recomputing the ratio gives -4."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD1-122', 'B', ARRAY['B']::TEXT[], '25% of 80 is 20, so the new price is 80 + 20 = 100 dollars. Always check by substituting the given values or factoring back out.', '{"C": "That is a decrease of 20 or a misapplied percent; a 25% increase adds 20 to 80.", "D": "A percent increase must grow the number: 25% of 80 = 20.", "A": "This corresponds to adding too little (or too much) of the 25% increase; recompute 25% of 80."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
