INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-QUA-134', 'D', ARRAY['D']::TEXT[], 'The vertex $x$-coordinate is $-\dfrac{b}{2a} = -\dfrac{-10}{2(1)} = 5$; with $a = 1 > 0$ this is the minimum. Always check by substituting the given values or factoring back out.', '{"A": "That value is not $-b/(2a)$: computing $a(-5)^2 + b(-5) + c$ does not produce the least output compared with $x = 5$.", "C": "That value is not $-b/(2a)$: computing $a(6)^2 + b(6) + c$ does not produce the least output compared with $x = 5$.", "B": "That value is not $-b/(2a)$: computing $a(10)^2 + b(10) + c$ does not produce the least output compared with $x = 5$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
