INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-159', 'D', ARRAY['D']::TEXT[], 'Sector area $= \dfrac{\theta}{360} \pi r^2 = \dfrac{60}{360} \pi(6)^2 = $ $6\pi$. Always check by substituting the given values or factoring back out.', '{"A": "Using $\\pi r^2$ without the $\\theta/360$ fraction gives the whole circle, not the sector.", "B": "Check the arithmetic: only $\\dfrac{60}{360}\\cdot36$ is correct.", "C": "That variant mis-scales the fraction; recompute $\\dfrac{\\theta}{360}\\cdot r^2$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
