INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-184', 'D', ARRAY['D']::TEXT[], 'A zero of a factored polynomial is any root of one of its linear factors: $x = 3$ makes the factor $(x - 3)$ equal to zero, so $h(3) = 0$. The other listed values are the remaining roots.', '{"A": "Substituting $x = 2$ into $(x - 2)(x - 3)(x - 5)$ yields a product of three nonzero factors, so it is not a zero.", "C": "Use the zero-product property: a value must zero one of the literal factors to be a zero of $h$.", "B": "Re-check each listed value against all three factors before accepting it as a zero."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-185', 'D', ARRAY['D']::TEXT[], 'A zero of a factored polynomial is any root of one of its linear factors: $x = 4$ makes the factor $(x - 4)$ equal to zero, so $h(4) = 0$. The other listed values are the remaining roots.', '{"B": "Substituting $x = 1$ into $(x - 1)(x - 4)(x - 6)$ yields a product of three nonzero factors, so it is not a zero.", "A": "Use the zero-product property: a value must zero one of the literal factors to be a zero of $h$.", "C": "Re-check each listed value against all three factors before accepting it as a zero."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-186', 'D', ARRAY['D']::TEXT[], 'A zero of a factored polynomial is any root of one of its linear factors: $x = 5$ makes the factor $(x - 5)$ equal to zero, so $h(5) = 0$. The other listed values are the remaining roots.', '{"C": "Substituting $x = 3$ into $(x - 3)(x - 5)(x - 7)$ yields a product of three nonzero factors, so it is not a zero.", "A": "Use the zero-product property: a value must zero one of the literal factors to be a zero of $h$.", "B": "Re-check each listed value against all three factors before accepting it as a zero."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-187', 'C', ARRAY['C']::TEXT[], 'A zero of a factored polynomial is any root of one of its linear factors: $x = 6$ makes the factor $(x - 6)$ equal to zero, so $h(6) = 0$. The other listed values are the remaining roots.', '{"B": "Substituting $x = 2$ into $(x - 2)(x - 6)(x - 9)$ yields a product of three nonzero factors, so it is not a zero.", "A": "Use the zero-product property: a value must zero one of the literal factors to be a zero of $h$.", "D": "Re-check each listed value against all three factors before accepting it as a zero."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-188', 'A', ARRAY['A']::TEXT[], 'Subtract 9: $3x > 18$. Dividing by the positive coefficient $3$ keeps the direction: $x > 6$. Always check by substituting the given values or factoring back out.', '{"B": "Reversing the inequality is wrong because we divide by the positive number $3$, not a negative one.", "D": "Shifting the boundary by 2 stretches the interval; the exact boundary is $6$.", "C": "A ''>'' flips to ''<'' only when dividing by a negative number, which never happens with $3$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-189', 'B', ARRAY['B']::TEXT[], 'Subtract 4: $5x > 25$. Dividing by the positive coefficient $5$ keeps the direction: $x > 5$. Always check by substituting the given values or factoring back out.', '{"D": "Reversing the inequality is wrong because we divide by the positive number $5$, not a negative one.", "A": "Shifting the boundary by 2 stretches the interval; the exact boundary is $5$.", "C": "A ''>'' flips to ''<'' only when dividing by a negative number, which never happens with $5$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-190', 'D', ARRAY['D']::TEXT[], 'Subtract 6: $4x > 24$. Dividing by the positive coefficient $4$ keeps the direction: $x > 6$. Always check by substituting the given values or factoring back out.', '{"B": "Reversing the inequality is wrong because we divide by the positive number $4$, not a negative one.", "C": "Shifting the boundary by 2 stretches the interval; the exact boundary is $6$.", "A": "A ''>'' flips to ''<'' only when dividing by a negative number, which never happens with $4$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALE-191', 'A', ARRAY['A']::TEXT[], 'Subtract 2: $6x > 24$. Dividing by the positive coefficient $6$ keeps the direction: $x > 4$. Always check by substituting the given values or factoring back out.', '{"C": "Reversing the inequality is wrong because we divide by the positive number $6$, not a negative one.", "B": "Shifting the boundary by 2 stretches the interval; the exact boundary is $4$.", "D": "A ''>'' flips to ''<'' only when dividing by a negative number, which never happens with $6$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-SYS-192', 'A', ARRAY['A']::TEXT[], 'Substitute $(x,y) = (4,3)$: $2(4) + 1(3) = 11$ and $1(4) + 4(3) = 16$. Both equations hold, so the pair solves the system.', '{"C": "Testing the swapped pair in the first equation gives $10$, not 11.", "B": "Off-by-one pairs fail: $2(5) + 1(2) = 12$, which is not 11.", "D": "Adding 2 to $y$ breaks the balance: $1(4) + 4(5) = 24$, not 16."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-SYS-193', 'A', ARRAY['A']::TEXT[], 'Substitute $(x,y) = (6,2)$: $3(6) + 2(2) = 22$ and $5(6) + 1(2) = 32$. Both equations hold, so the pair solves the system.', '{"C": "Testing the swapped pair in the first equation gives $18$, not 22.", "B": "Off-by-one pairs fail: $3(7) + 2(1) = 23$, which is not 22.", "D": "Adding 2 to $y$ breaks the balance: $5(6) + 1(4) = 34$, not 32."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-SYS-194', 'D', ARRAY['D']::TEXT[], 'Substitute $(x,y) = (5,4)$: $1(5) + 3(4) = 17$ and $2(5) + 5(4) = 30$. Both equations hold, so the pair solves the system.', '{"A": "Testing the swapped pair in the first equation gives $19$, not 17.", "C": "Off-by-one pairs fail: $1(6) + 3(3) = 15$, which is not 17.", "B": "Adding 2 to $y$ breaks the balance: $2(5) + 5(6) = 40$, not 30."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-SYS-195', 'C', ARRAY['C']::TEXT[], 'Substitute $(x,y) = (7,1)$: $4(7) + 3(1) = 31$ and $2(7) + 9(1) = 23$. Both equations hold, so the pair solves the system.', '{"D": "Testing the swapped pair in the first equation gives $25$, not 31.", "B": "Off-by-one pairs fail: $4(8) + 3(0) = 32$, which is not 31.", "A": "Adding 2 to $y$ breaks the balance: $2(7) + 9(3) = 41$, not 23."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-196', '5', ARRAY['5', '5.0']::TEXT[], 'In a 30-60-90 triangle the legs are $x$ and $x\sqrt3$ with hypotenuse $2x$. Here $2x = 10$, so $x = 5$. Always check by substituting the given values or factoring back out.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-196-2', '7sqrt(2)', ARRAY['7sqrt(2)', '7sqrt(2).0']::TEXT[], 'In a 45-45-90 triangle the hypotenuse is $\sqrt2$ times a leg: $7\sqrt2$. Always check by substituting the given values or factoring back out.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-196-3', '3/4', ARRAY['3/4']::TEXT[], '$\tan A = \dfrac{\sin A}{\cos A} = \dfrac{3/5}{4/5} = \dfrac{3}{4}$. Always check by substituting the given values or factoring back out.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
