INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-204', 'D', ARRAY['D']::TEXT[], '$V = \pi r^2 h = \pi (3)^2 (5) = 45\pi$ cubic units. Always check by substituting the given values or factoring back out.', '{"B": "That variant uses a wrong power or wrong factor; only $\\pi r^2 h$ with $r = 3$, $h = 5$ gives 45.", "A": "Check the formula: cylinders use $\\pi r^2 h$, then substitute.", "C": "Recompute $r^2$ before multiplying by the height."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
