INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-100', 'D', ARRAY['D']::TEXT[], 'The two clauses are neither causal nor contrastive; a plain coordinating conjunction joins them. Reread the sentence with the chosen answer in place to confirm it fits.', '{"B": "That option breaks the convention tested here - splice, agreement, word form, or wrong conjunction.", "A": "Substituting it back, the sentence no longer holds together under standard rules.", "C": "This creates a fused clause, an agreement error, or a mismatched word class."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
