INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-300', 'B', ARRAY['B']::TEXT[], 'The passage''s claim is that the down-slope spring move trades bloom access for delayed foraging caused by overnight cold; that is the through-line of the two sentences.', '{"C": "Autumn abundance and denying the move are both inventions; the passage says nothing about either.", "D": "The passage says winds are calmer at the higher winter site, not stronger on the plateau.", "A": "No refusal to move is reported; the text describes why the move carries a cost."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-301', 'C', ARRAY['C']::TEXT[], 'The passage contrasts the old river method with cheaper in-house washing that used half the water; the natural completion is that the new technology eliminated the old one on cost.', '{"A": "The passage states the steam laundries used half the water, not more.", "B": "No ordinance or pollution complaint is mentioned.", "D": "Nothing suggests transport difficulty; the wharves became unnecessary."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-302', 'A', ARRAY['A']::TEXT[], 'The quotation shows a purchase-plus-payment status written where patrons could read it, which is exactly the ''informal credit registry'' the historian describes.', '{"C": "Reading the news aloud describes sociability, not credit tracked in public.", "B": "Whitewashing and mint potting are housekeeping details with no bearing on ledgers.", "D": "Storage of cocoa tells us about supply, not the public display of debts."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-303', 'C', ARRAY['C']::TEXT[], 'The passage moves from a popular simplification to the specific omitted stages - purification, trials, mass production - which is a correction-by-addition structure.', '{"D": "The focus is the full chain from discovery to drug, not a single experiment.", "B": "Fleming''s discovery remains credited first; the later stages are supplements, not rivals.", "A": "Equipment is never itemized; the passage evaluates the fairness of the story."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
