INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-QUA-55751', 'B', ARRAY['B']::TEXT[], 'The vertex $x$-coordinate is $-\dfrac{b}{2a} = -\dfrac{-2}{2(1)} = 1$; with $a = 1 > 0$ the parabola opens upward. Always check by substituting the given values or factoring back out.', '{"C": "That value is not $-b/(2a)$; evaluate $f$ there and compare it with $f$ at the vertex.", "D": "Only $-b/2a$ gives the axis of symmetry of the parabola.", "A": "Recompute $-b/(2a)$ carefully with the given coefficients."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
