INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-56101', 'C', ARRAY['C']::TEXT[], 'Sector area $= \dfrac{\theta}{360}\pi r^2 = \dfrac{30}{360}\pi(2)^2 = $ $\dfrac{1}{3}\pi$. Always check by substituting the given values or factoring back out.', '{"A": "That variant mis-scales the fraction; recompute (theta/360) times r squared.", "B": "Without the theta/360 factor you get the whole circle, not the sector.", "D": "Check the arithmetic before selecting the multiple of pi."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
