INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-100', 'formula', 'formula', 'Linear slope', NULL, 'Slope from two points: rise over run.', 'm=\dfrac{y_2-y_1}{x_2-x_1}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-101', 'formula', 'formula', 'Slope from standard form', NULL, 'In standard form, slope is negative A over B.', 'Ax+By=C \Rightarrow m=-\dfrac{A}{B}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-102', 'formula', 'formula', 'Point-slope form', NULL, 'Line of slope m through (x1, y1).', 'y-y_1=m(x-x_1)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-103', 'formula', 'formula', 'Parallel lines', NULL, 'Parallel lines share slopes.', 'm_1=m_2', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-104', 'formula', 'formula', 'Perpendicular slopes', NULL, 'Perpendicular slopes multiply to -1 (negative reciprocals).', 'm_1 m_2=-1', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-105', 'formula', 'formula', 'Midpoint formula', NULL, 'Average the coordinates for the midpoint.', '\left(\dfrac{x_1+x_2}{2},\dfrac{y_1+y_2}{2}\right)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-106', 'formula', 'formula', 'Distance formula', NULL, 'Pythagoras between two points.', 'd=\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-107', 'formula', 'formula', 'Quadratic formula', NULL, 'General solution of ax^2+bx+c=0.', 'x=\dfrac{-b\pm\sqrt{b^2-4ac}}{2a}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-108', 'formula', 'formula', 'Discriminant count', NULL, 'Sign of the discriminant fixes root counts.', 'b^2-4ac>0: 2\text{ real},=0: 1,<0: 0', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-109', 'formula', 'formula', 'Vertex x-coordinate', NULL, 'Axis of symmetry of a parabola.', 'x=-\dfrac{b}{2a}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-110', 'formula', 'formula', 'Vertex y-coordinate', NULL, 'Minimum or maximum value of a quadratic.', 'f(-b/2a)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-111', 'formula', 'formula', 'Zeros product', NULL, 'Product of quadratic roots equals c/a.', 'r_1 r_2=\dfrac{c}{a}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-112', 'formula', 'formula', 'Zeros sum', NULL, 'Sum of quadratic roots equals -b/a.', 'r_1+r_2=-\dfrac{b}{a}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-113', 'formula', 'formula', 'Difference of squares', NULL, 'Fast factoring identity.', 'a^2-b^2=(a-b)(a+b)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-114', 'formula', 'formula', 'Perfect square trinomial', NULL, 'Square of a binomial.', '(a\pm b)^2=a^2\pm 2ab+b^2', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-115', 'formula', 'formula', 'Cubic difference', NULL, 'Difference of cubes factoring.', 'a^3-b^3=(a-b)(a^2+ab+b^2)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-116', 'formula', 'formula', 'Cubic sum', NULL, 'Sum of cubes factoring.', 'a^3+b^3=(a+b)(a^2-ab+b^2)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-117', 'formula', 'formula', 'Exponent product', NULL, 'Multiply powers: add exponents.', 'a^m a^n=a^{m+n}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-118', 'formula', 'formula', 'Exponent quotient', NULL, 'Divide powers: subtract exponents.', '\dfrac{a^m}{a^n}=a^{m-n}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-119', 'formula', 'formula', 'Power of a power', NULL, 'Raise a power: multiply exponents.', '(a^m)^n=a^{mn}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
